.demo-back .pixel-icon, .demo-pause .pixel-icon { font-size: 11px; }
.demo-back:hover, .demo-pause:hover { color: var(--gold); border-color: var(--gold); }
.demo-pause { width: 34px; padding: 0; justify-content: center; font-size: 13px; }
.demo-title { display: flex; flex-direction: column; align-items: center; gap: 5px; margin-top: 2px; text-align: center; }
.demo-kicker { font-family: var(--font-pixel); font-size: 8px; letter-spacing: 0.18em; color: var(--gold); text-shadow: 2px 2px 0 #000; }
.demo-room { font-family: var(--font-pixel); font-size: 5px; letter-spacing: 0.12em; color: var(--muted); }

.demo-hud {
  position: absolute;
  left: 14px;
