}
.hud-label { color: var(--red); font-size: 6px; }
.hp-track { width: 92px; height: 7px; border: 1px solid rgba(255, 255, 255, 0.25); padding: 1px; background: rgba(0, 0, 0, 0.55); }
.hp-track span { display: block; width: 100%; height: 100%; background: var(--gold); transition: width 0.14s steps(3); }
