export async function downloadWithProgress(url, onProgress, signal) {
  const response = await fetch(url, { mode: 'cors', credentials: 'omit', signal });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const total = Number(response.headers.get('content-length')) || 0;
  if (!response.body) {
    const blob = await response.blob();
    onProgress?.(blob.size, total || blob.size);
    return blob;
  }
  const reader = response.body.getReader();
  const chunks = [];
  let received = 0;
  let last = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.length;
    const now = performance.now();
    if (now - last > 80 || received === total) {
      last = now;
      onProgress?.(received, total);
    }
  }
  const blob = new Blob(chunks, { type: response.headers.get('content-type') || 'application/octet-stream' });
  onProgress?.(received, total || received);
  return blob;
}

export function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = sanitizeFilename(filename);
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

export async function exportMod(record) {
  let blob = await getModBlob(record.id);
  if (!blob && record.pack) {
    blob = new Blob([JSON.stringify(record.pack, null, 2)], { type: 'application/json' });
  }
  if (!blob) throw new Error('File data is missing');
  const fallback = record.kind === 'pack' ? `${record.name}.utmod` : 'data.win';
  downloadBlob(blob, record.fileName || fallback);
}

export function sanitizeFilename(name) {
  return String(name || 'mod').replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').trim().slice(0, 120) || 'mod';
}

export function formatBytes(bytes) {
  const n = Number(bytes) || 0;
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(n < 10 * 1024 ? 1 : 0)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(n < 10 * 1024 * 1024 ? 1 : 0)} MB`;
  return `${(n / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

export async function storageInfo(mods) {
  let quota = 0;
  let usage = 0;
  try {
    if (navigator.storage?.estimate) {
      const estimate = await navigator.storage.estimate();
      quota = estimate.quota || 0;
      usage = estimate.usage || 0;
    }
  } catch { /* ignore */ }
  const modBytes = (mods || []).reduce((sum, mod) => sum + (Number(mod.size) || 0), 0);
  return { quota, usage, modBytes, used: modBytes || usage };
}

let modalEl = null;
let lastFocus = null;
let modalDismissible = true;
let onModalClose = null;

export function icon(name, className = 'pixel-icon') {
  return `<svg class="${className}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
}

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function toast(message, type = 'info', timeout = 4200) {
  const root = document.getElementById('toastRoot');
  if (!root) return;
  const el = document.createElement('div');
  el.className = `toast is-${type}`;
  const iconName = type === 'error' ? 'close' : type === 'ok' ? 'check' : 'heart';
  el.innerHTML = `${icon(iconName)}<span>${escapeHtml(message)}</span>`;
  el.setAttribute('role', type === 'error' ? 'alert' : 'status');
  root.appendChild(el);
  while (root.children.length > 4) root.firstElementChild?.remove();
  setTimeout(() => {
    el.classList.add('is-out');
    setTimeout(() => el.remove(), 320);
  }, timeout);
}

export function openModal(html, options = {}) {
  closeModal({ silent: true });
  const root = document.getElementById('modalRoot');
  if (!root) return null;
  lastFocus = document.activeElement;
  modalDismissible = options.dismissible !== false;
  onModalClose = options.onClose || null;

  const backdrop = document.createElement('div');
  backdrop.className = 'modal-backdrop';
  const card = document.createElement('div');
  card.className = `modal-card ${options.className || ''}`.trim();
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-modal', 'true');
  if (options.labelledBy) card.setAttribute('aria-labelledby', options.labelledBy);
  card.innerHTML = `${options.showClose === false ? '' : `<button class="modal-close" type="button" data-modal-close aria-label="Close">${icon('close')}</button>`}${html}`;
  backdrop.appendChild(card);
  root.appendChild(backdrop);
  modalEl = { backdrop, card };

  backdrop.addEventListener('click', (event) => {
    if (event.target === backdrop && modalDismissible) closeModal();
  });
  card.addEventListener('click', (event) => {
    const close = event.target.closest('[data-modal-close]');
    if (close) { event.preventDefault(); closeModal(); }
  });

  const onKey = (event) => {
    if (!modalEl || !modalDismissible) return;
    if (event.key === 'Escape') { event.preventDefault(); closeModal(); }
  };
  document.addEventListener('keydown', onKey);
  backdrop._onKey = onKey;

  options.onMount?.(card, closeModal);

  requestAnimationFrame(() => {
    const focusable = card.querySelector('[autofocus], button:not([disabled]), input, a[href]');
    focusable?.focus?.({ preventScroll: true });
  });

  return card;
}

export function closeModal({ silent = false } = {}) {
  const root = document.getElementById('modalRoot');
  if (!modalEl) return;
  const { backdrop } = modalEl;
  if (backdrop?._onKey) document.removeEventListener('keydown', backdrop._onKey);
  backdrop?.remove();
  modalEl = null;
  const callback = onModalClose;
  onModalClose = null;
  if (!silent) lastFocus?.focus?.({ preventScroll: true });
  lastFocus = null;
  if (typeof callback === 'function') callback();
  if (root) root.innerHTML = '';
}

export function isModalOpen() { return Boolean(modalEl); }

export function confirmDialog({
  title,
  text,
  confirmLabel = 'OK',
  cancelLabel = 'CANCEL',
  danger = false
}) {
  return new Promise((resolve) => {
    let resolved = false;
    const finish = (value) => {
      if (resolved) return;
      resolved = true;
      resolve(value);
    };
    openModal(
      `<div class="modal-small">
        <h2>${escapeHtml(title)}</h2>
        <p>${escapeHtml(text)}</p>
        <div class="modal-actions">
          <button class="pixel-btn ghost" type="button" data-confirm-cancel>${escapeHtml(cancelLabel)}</button>
          <button class="pixel-btn ${danger ? 'danger' : ''}" type="button" data-confirm-ok>${escapeHtml(confirmLabel)}</button>
        </div>
      </div>`,
      {
        className: 'confirm-modal',
        showClose: false,
        dismissible: true,
        onClose: () => finish(false),
        onMount(card, close) {
          card.querySelector('[data-confirm-cancel]')?.addEventListener('click', () => { finish(false); close(); });
          card.querySelector('[data-confirm-ok]')?.addEventListener('click', () => { finish(true); close(); });
        }
      }
    );
  });
}

export function busyButton(button, label) {
  if (!button) return () => {};
  const original = button.innerHTML;
  button.disabled = true;
  button.innerHTML = `<span class="spin-dot"></span>${escapeHtml(label)}`;
  return () => {
    button.disabled = false;
    button.innerHTML = original;
  };
}

export function flash(color = 'white') {
  const el = document.getElementById('flash');
  if (!el) return;
  el.style.background = color;
  el.classList.remove('is-on');
  void el.offsetWidth;
  el.classList.add('is-on');
  setTimeout(() => el.classList.remove('is-on'), 500);
}

export function timeAgo(timestamp, lang = 'ru') {
  const value = Number(timestamp);
  if (!value) return '';
  const seconds = Math.max(0, Math.floor(Date.now() / 1000 - value));
  const day = 86_400;
  if (seconds < 3600) {
    const mins = Math.max(1, Math.floor(seconds / 60));
    return lang === 'ru' ? `${mins} мин назад` : `${mins} min ago`;
  }
  if (seconds < day) {
    const hours = Math.floor(seconds / 3600);
    return lang === 'ru' ? `${hours} ч назад` : `${hours} h ago`;
  }
  if (seconds < day * 2) return lang === 'ru' ? 'вчера' : 'yesterday';
  if (seconds < day * 30) {
    const days = Math.floor(seconds / day);
    return lang === 'ru' ? `${days} дн. назад` : `${days} d ago`;
  }
  if (seconds < day * 365) {
    const months = Math.floor(seconds / (day * 30));
    return lang === 'ru' ? `${months} мес. назад` : `${months} mo ago`;
  }
  const years = Math.floor(seconds / (day * 365));
  return lang === 'ru' ? `${years} г. назад` : `${years} y ago`;
}

export const GAME_ID = 5506;
export const GAME_URL = `https://gamebanana.com/games/${GAME_ID}`;
const API = 'https://gamebanana.com/apiv11';

export class GameBananaError extends Error {
  constructor(message, { code = 'network', status = 0 } = {}) {
    super(message);
    this.name = 'GameBananaError';
    this.code = code;
    this.status = status;
  }
}

async function fetchJSON(url, { signal, timeout = 25_000 } = {}) {
  if (navigator.onLine === false) throw new GameBananaError('Offline', { code: 'offline' });
  const controller = new AbortController();
  let timedOut = false;
  const timer = setTimeout(() => { timedOut = true; controller.abort(); }, timeout);
  const abort = () => controller.abort();
  signal?.addEventListener('abort', abort, { once: true });
  try {
    const response = await fetch(url, {
      headers: { Accept: 'application/json' },
      mode: 'cors',
      credentials: 'omit',
      signal: controller.signal
    });
    if (!response.ok) throw new GameBananaError(`HTTP ${response.status}`, { code: 'http', status: response.status });
    return await response.json();
  } catch (error) {
    if (error?.name === 'GameBananaError') throw error;
    if (signal?.aborted) throw new GameBananaError('Aborted', { code: 'aborted' });
    if (timedOut) throw new GameBananaError('Timeout', { code: 'timeout' });
    throw new GameBananaError('Network error', { code: 'network' });
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener('abort', abort);
  }
}

export function imageUrl(image, size = '530') {
  if (!image) return '';
  const file = size === '220' && image._sFile220
    ? image._sFile220
    : size === '100' && image._sFile100
      ? image._sFile100
      : size === '530' && image._sFile530
        ? image._sFile530
        : image._sFile;
  if (!file) return '';
  return `${image._sBaseUrl}/${file}`;
}

function mapRecord(record) {
  const image = record._aPreviewMedia?._aImages?.[0];
  const category = record._aRootCategory?._sName || record._aCategory?._sName || 'Mod';
  return {
    id: Number(record._idRow),
    name: record._sName || 'Untitled mod',
    profileUrl: record._sProfileUrl || `https://gamebanana.com/mods/${record._idRow}`,
    author: record._aSubmitter?._sName || 'Unknown',
    authorUrl: record._aSubmitter?._sProfileUrl || '',
    authorAvatar: record._aSubmitter?._sAvatarUrl || '',
    category,
    version: record._sVersion || '',
    likes: Number(record._nLikeCount) || 0,
    views: Number(record._nViewCount) || 0,
    posts: Number(record._nPostCount) || 0,
    dateAdded: Number(record._tsDateAdded) || 0,
    dateUpdated: Number(record._tsDateUpdated || record._tsDateModified || record._tsDateAdded) || 0,
    hasFiles: Boolean(record._bHasFiles),
    obsolete: Boolean(record._bIsObsolete),
    game: record._aGame ? { id: Number(record._aGame._idRow), name: record._aGame._sName } : null,
    cover: imageUrl(image, '530'),
    coverSmall: imageUrl(image, '220') || imageUrl(image, '100'),
    screens: (record._aPreviewMedia?._aImages || []).map((img) => ({
      full: imageUrl(img, 'full'),
      large: imageUrl(img, '530'),
      small: imageUrl(img, '220'),
      caption: img._sCaption || ''
    })).filter((img) => img.large),
    raw: record
  };
}

function mapDetail(record) {
  const base = mapRecord(record);
  return {
    ...base,
    description: htmlToText(record._sText || record._sDescription || ''),
    shortDescription: htmlToText(record._sDescription || ''),
    downloads: Number(record._nDownloadCount) || 0,
    files: (record._aFiles || []).map((file) => ({
      id: Number(file._idRow),
      name: file._sFile || `file-${file._idRow}`,
      size: Number(file._nFilesize) || 0,
      date: Number(file._tsDateAdded) || 0,
      downloads: Number(file._nDownloadCount) || 0,
      url: file._sDownloadUrl || '',
      md5: file._sMd5Checksum || '',
      analysis: file._sAnalysisResult || '',
      av: file._sAvResult || '',
      description: file._sDescription || ''
    })),
    images: (record._aPreviewMedia?._aImages || []).map((img) => ({
      large: imageUrl(img, '530'),
      small: imageUrl(img, '220'),
      caption: img._sCaption || ''
    })).filter((img) => img.large),
    credits: record._aCredits || []
  };
}

export async function browseMods({ sort = 'default', page = 1, signal } = {}) {
  const safeSort = ['default', 'new', 'updated'].includes(sort) ? sort : 'default';
  const url = `${API}/Game/${GAME_ID}/Subfeed?_nPage=${page}&_sSort=${safeSort}`;
  const data = await fetchJSON(url, { signal });
  const records = (data._aRecords || []).map(mapRecord);
  return {
    records,
    total: Number(data._aMetadata?._nRecordCount) || 0,
    page,
    more: !data._aMetadata?._bIsComplete,
    perPage: Number(data._aMetadata?._nPerpage) || records.length
  };
}

export async function searchMods({ query, page = 1, signal }) {
  const text = String(query || '').trim();
  if (!text) return { records: [], total: 0, page, more: false };
  const url = `${API}/Util/Search/Results?_sSearchString=${encodeURIComponent(text)}&_sModelName=Mod&_nPage=${page}`;
  const data = await fetchJSON(url, { signal });
  const records = (data._aRecords || [])
    .filter((record) => Number(record._aGame?._idRow) === GAME_ID)
    .map(mapRecord);
  return {
    records,
    total: records.length,
    page,
    more: !data._aMetadata?._bIsComplete
  };
}

export async function fetchModDetail(id, { signal } = {}) {
  if (!id) throw new GameBananaError('Missing mod id', { code: 'input' });
  const data = await fetchJSON(`${API}/Mod/${id}/ProfilePage`, { signal });
  if (!data || !data._idRow) throw new GameBananaError('Mod not found', { code: 'notfound' });
  return mapDetail(data);
}

export function htmlToText(html) {
  if (!html) return '';
  let source = String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|h[1-6]|ul|ol)>/gi, '\n\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/li>/gi, '\n');
  try {
    const doc = new DOMParser().parseFromString(`<div>${source}</div>`, 'text/html');
    source = doc.body.textContent || '';
  } catch {
    source = source.replace(/<[^>]+>/g, ' ');
  }
  return source
    .replace(/\u00a0/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, 14_000);
}

export function modFileKind(file) {
  const name = String(file?.name || '').toLowerCase();
  if (name.endsWith('.win')) return 'data.win';
  if (name.endsWith('.zip')) return 'ZIP';
  if (name.endsWith('.utmod') || name.endsWith('.json')) return '.utmod';
  return 'FILE';
}

const NOTE = (midi) => 440 * Math.pow(2, (midi - 69) / 12);

const MENU_LEAD = [
  62, 65, 69, 65, 64, 67, 69, null,
  62, 65, 69, 72, 69, 65, 64, 62,
  65, 69, 72, 69, 67, 65, 64, null,
  62, 64, 65, 67, 69, 72, 74, null
];
const MENU_BASS = [38, null, null, null, 41, null, null, null, 36, null, null, null, 41, null, null, null];

const GAME_LEAD = [
  69, 72, 76, 72, 74, 72, 69, 67,
  69, 72, 76, 79, 76, 72, 69, 67,
  65, 69, 72, 69, 67, 65, 64, 62,
  69, 72, 74, 76, 74, 72, 69, null
];
const GAME_BASS = [45, null, null, null, 41, null, null, null, 38, null, null, null, 40, null, null, null];

export class ChipAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.delay = null;
    this.noise = null;
    this.unlocked = false;
    this.muted = false;
    this.musicVolume = 0.45;
    this.sfxVolume = 0.7;
    this.theme = 'menu';
    this.tempoMultiplier = 1;
    this.timer = null;
    this.nextTime = 0;
    this.step = 0;
    this.playing = false;
    this._visHandler = () => {
      if (!this.ctx) return;
      if (document.hidden) this.ctx.suspend().catch(() => {});
      else if (this.unlocked) this.ctx.resume().catch(() => {});
    };
  }

  ensure() {
    if (this.ctx) return this.ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.85;
    this.master.connect(ctx.destination);

    this.musicGain = ctx.createGain();
    this.musicGain.gain.value = this.musicVolume * 0.6;
    this.musicGain.connect(this.master);

    this.sfxGain = ctx.createGain();
    this.sfxGain.gain.value = this.sfxVolume;
    this.sfxGain.connect(this.master);

    this.delay = ctx.createDelay(0.6);
    this.delay.delayTime.value = 0.27;
    const feedback = ctx.createGain();
    feedback.gain.value = 0.18;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1700;
    this.delay.connect(feedback);
    feedback.connect(this.delay);
    this.delay.connect(filter);
    filter.connect(this.musicGain);

    document.addEventListener('visibilitychange', this._visHandler);
    return ctx;
  }

  async unlock() {
    const ctx = this.ensure();
    if (!ctx) return;
    if (ctx.state === 'suspended') {
      try { await ctx.resume(); } catch { /* ignore */ }
    }
    if (!this.unlocked) {
      this.unlocked = true;
      this.startMusic();
    }
  }

  setVolumes(music, sfx, muted = this.muted) {
    this.musicVolume = Math.min(1, Math.max(0, music / 100));
    this.sfxVolume = Math.min(1, Math.max(0, sfx / 100));
    this.muted = Boolean(muted);
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.musicGain.gain.setTargetAtTime(this.musicVolume * 0.6, now, 0.03);
    this.sfxGain.gain.setTargetAtTime(this.sfxVolume, now, 0.02);
    this.master.gain.setTargetAtTime(this.muted ? 0 : 0.85, now, 0.02);
  }

  setMuted(muted) {
    this.muted = Boolean(muted);
    if (this.ctx) this.master.gain.setTargetAtTime(this.muted ? 0 : 0.85, this.ctx.currentTime, 0.03);
  }

  tone({ freq, endFreq, type = 'square', duration = 0.08, volume = 0.08, when = 0, attack = 0.004, destination = this.sfxGain }) {
    const ctx = this.ctx;
    if (!ctx || this.muted || this.sfxVolume <= 0) return;
    const dest = destination || this.sfxGain;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const start = ctx.currentTime + when;
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), start);
    if (endFreq) osc.frequency.linearRampToValueAtTime(Math.max(20, endFreq), start + duration);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.linearRampToValueAtTime(volume, start + attack);
    gain.gain.linearRampToValueAtTime(0.0001, start + duration);
    osc.connect(gain);
    gain.connect(dest);
    osc.start(start);
    osc.stop(start + duration + 0.03);
  }

  noiseBurst({ duration = 0.12, volume = 0.18, filter = 1200, when = 0 } = {}) {
    const ctx = this.ctx;
    if (!ctx || this.muted || this.sfxVolume <= 0) return;
    if (!this.noise) {
      const length = Math.floor(ctx.sampleRate * 0.35);
      const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
      this.noise = buffer;
    }
    const source = ctx.createBufferSource();
    source.buffer = this.noise;
    const bp = ctx.createBiquadFilter();
    bp.type = 'lowpass';
    bp.frequency.value = filter;
    const gain = ctx.createGain();
    const start = ctx.currentTime + when;
    gain.gain.setValueAtTime(volume, start);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    source.connect(bp);
    bp.connect(gain);
    gain.connect(this.sfxGain);
    source.start(start);
    source.stop(start + duration + 0.02);
  }

  play(name) {
    if (!this.unlocked) return;
    const ctx = this.ensure();
    if (!ctx) return;
    switch (name) {
      case 'move':
        this.tone({ freq: 620, endFreq: 700, type: 'square', duration: 0.035, volume: 0.035 });
        break;
      case 'select':
        this.tone({ freq: 523, duration: 0.05, volume: 0.07 });
        this.tone({ freq: 784, duration: 0.09, volume: 0.07, when: 0.055 });
        break;
      case 'back':
        this.tone({ freq: 392, endFreq: 294, type: 'triangle', duration: 0.1, volume: 0.07 });
        break;
      case 'error':
        this.tone({ freq: 150, endFreq: 95, type: 'sawtooth', duration: 0.18, volume: 0.07 });
        break;
      case 'type':
        this.tone({ freq: 440 + Math.random() * 180, type: 'square', duration: 0.018, volume: 0.012 });
        break;
      case 'hit':
        this.noiseBurst({ duration: 0.16, volume: 0.2, filter: 900 });
        this.tone({ freq: 110, endFreq: 55, type: 'square', duration: 0.16, volume: 0.1 });
        break;
      case 'heal':
        [523, 659, 784, 1046].forEach((freq, i) => this.tone({ freq, type: 'sine', duration: 0.16, volume: 0.06, when: i * 0.07 }));
        break;
      case 'download':
        this.tone({ freq: 330, endFreq: 440, type: 'square', duration: 0.09, volume: 0.05 });
        break;
      case 'success':
        [523, 659, 784, 1046].forEach((freq, i) => this.tone({ freq, type: 'square', duration: 0.2, volume: 0.06, when: i * 0.1 }));
        break;
      case 'unlock':
        [440, 554, 659, 880, 1108].forEach((freq, i) => this.tone({ freq, type: 'triangle', duration: 0.32, volume: 0.08, when: i * 0.11 }));
        this.noiseBurst({ duration: 0.4, volume: 0.03, filter: 3000, when: 0.4 });
        break;
      case 'boot':
        this.tone({ freq: 110, endFreq: 440, type: 'triangle', duration: 0.6, volume: 0.05 });
        this.tone({ freq: 220, endFreq: 880, type: 'sine', duration: 0.5, volume: 0.04, when: 0.1 });
        break;
      case 'clear':
        [523, 659, 784, 1046, 1318].forEach((freq, i) => this.tone({ freq, type: 'square', duration: 0.32, volume: 0.07, when: i * 0.12 }));
        break;
      default:
        break;
    }
  }

  startMusic(theme = this.theme, tempoMultiplier = this.tempoMultiplier) {
    if (!this.ctx) return;
    this.theme = theme;
    this.tempoMultiplier = tempoMultiplier || 1;
    if (this.playing) return;
    this.playing = true;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.timer = setInterval(() => this.schedule(), 90);
    this.schedule();
  }

  setTheme(theme, tempoMultiplier = 1) {
    if (theme === this.theme && Math.abs(tempoMultiplier - this.tempoMultiplier) < 0.01) {
      if (this.ctx && !this.playing) this.startMusic(theme, tempoMultiplier);
      return;
    }
    this.theme = theme;
    this.tempoMultiplier = tempoMultiplier || 1;
    this.step = 0;
    if (this.ctx) this.nextTime = this.ctx.currentTime + 0.08;
  }

  stopMusic() {
    this.playing = false;
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  schedule() {
    if (!this.ctx || !this.playing) return;
    const lookahead = this.ctx.currentTime + 0.35;
    const bpm = this.theme === 'game' ? 104 * this.tempoMultiplier : 82 * this.tempoMultiplier;
    const stepDur = 60 / bpm / 2;
    while (this.nextTime < lookahead) {
      this.scheduleStep(this.step, this.nextTime, stepDur);
      this.nextTime += stepDur;
      this.step = (this.step + 1) % 32;
    }
  }

  scheduleStep(step, when, stepDur) {
    if (!this.ctx || this.musicVolume <= 0) return;
    const lead = this.theme === 'game' ? GAME_LEAD : MENU_LEAD;
    const bass = this.theme === 'game' ? GAME_BASS : MENU_BASS;
    const note = lead[step];
    if (note) {
      this.musicNote(NOTE(note), when, stepDur * 0.82, 'square', 0.032);
      if (this.theme === 'game' && step % 8 === 0) this.musicNote(NOTE(note + 12), when, stepDur * 0.5, 'triangle', 0.018);
    }
    const bassNote = bass[step];
    if (bassNote) this.musicNote(NOTE(bassNote), when, stepDur * 3.6, 'triangle', 0.05);
    if (step % 8 === 0) {
      const chord = this.theme === 'game' ? [57, 60, 64] : [50, 53, 57];
      chord.forEach((midi, i) => this.musicNote(NOTE(midi), when + i * 0.012, stepDur * 7.2, 'sine', 0.012));
    }
  }

  musicNote(freq, when, duration, type, volume) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, when);
    gain.gain.setValueAtTime(0.0001, when);
    gain.gain.linearRampToValueAtTime(volume, when + 0.012);
    gain.gain.linearRampToValueAtTime(0.0001, when + duration);
    osc.connect(gain);
    gain.connect(this.musicGain);
    gain.connect(this.delay);
    osc.start(when);
    osc.stop(when + duration + 0.02);
  }
}

export const audio = new ChipAudio();

function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class RuinsScene {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.width = 480;
    this.height = 270;
    canvas.width = this.width;
    canvas.height = this.height;
    this.ctx.imageSmoothingEnabled = false;

    this.running = false;
    this.last = 0;
    this.time = 0;
    this.motion = true;
    this.px = 0;
    this.py = 0;
    this.tx = 0;
    this.ty = 0;

    const rand = mulberry32(1337);
    this.dust = Array.from({ length: 34 }, () => ({
      x: rand() * this.width,
      y: rand() * this.height,
      speed: 3 + rand() * 9,
      drift: (rand() - 0.5) * 5,
      size: rand() > 0.72 ? 2 : 1,
      phase: rand() * Math.PI * 2,
      alpha: 0.18 + rand() * 0.42
    }));
    this.leaves = Array.from({ length: 13 }, () => ({
      x: rand() * this.width,
      y: 20 + rand() * 225,
      speed: 6 + rand() * 13,
      drift: (rand() - 0.5) * 6,
      size: 2 + Math.floor(rand() * 2),
      phase: rand() * Math.PI * 2,
      alpha: 0.35 + rand() * 0.45
    }));
    this.fireflies = Array.from({ length: 7 }, () => ({
      x: 250 + rand() * 210,
      y: 140 + rand() * 90,
      phase: rand() * Math.PI * 2,
      speed: 0.2 + rand() * 0.4,
      radius: 6 + rand() * 10
    }));

    this.onPointer = (event) => {
      if (!this.motion) return;
      this.tx = (event.clientX / window.innerWidth - 0.5) * 2;
      this.ty = (event.clientY / window.innerHeight - 0.5) * 2;
    };
    this.onLeave = () => { this.tx = 0; this.ty = 0; };
    this.onVisibility = () => {
      if (document.hidden) this.stop();
      else this.start();
    };
    window.addEventListener('pointermove', this.onPointer, { passive: true });
    window.addEventListener('pointerleave', this.onLeave, { passive: true });
    document.addEventListener('visibilitychange', this.onVisibility);
  }

  setMotion(motion) {
    this.motion = Boolean(motion);
    if (!this.motion) { this.tx = 0; this.ty = 0; this.px = 0; this.py = 0; }
    this.draw(this.time);
  }

  start() {
    if (this.running || !this.ctx) return;
    this.running = true;
    this.last = performance.now();
    requestAnimationFrame((t) => this.loop(t));
  }

  stop() {
    this.running = false;
  }

  loop(now) {
    if (!this.running) return;
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    if (!document.hidden) {
      this.time += dt;
      this.update(dt);
      this.draw(this.time);
    }
    requestAnimationFrame((t) => this.loop(t));
  }

  update(dt) {
    const ease = this.motion ? 1 - Math.pow(0.002, dt) : 1;
    this.px += (this.tx - this.px) * ease;
    this.py += (this.ty - this.py) * ease;
    if (!this.motion) return;
    for (const leaf of this.leaves) {
      leaf.x += (leaf.speed + Math.sin(this.time * 0.7 + leaf.phase) * 3) * dt;
      leaf.y += (leaf.drift + Math.cos(this.time * 0.5 + leaf.phase) * 3) * dt;
      if (leaf.x > this.width + 8) { leaf.x = -8; leaf.y = 20 + Math.random() * 225; }
      if (leaf.y > this.height + 8) leaf.y = -8;
      if (leaf.y < -8) leaf.y = this.height + 8;
    }
    for (const dot of this.dust) {
      dot.y -= dot.speed * dt;
      dot.x += Math.sin(this.time * 0.35 + dot.phase) * dot.drift * dt;
      if (dot.y < -4) { dot.y = this.height + 4; dot.x = Math.random() * this.width; }
      if (dot.x < -4) dot.x = this.width + 4;
      if (dot.x > this.width + 4) dot.x = -4;
    }
  }

  draw(time) {
    const ctx = this.ctx;
    const w = this.width;
    const h = this.height;
    const px = this.px * 4;
    const py = this.py * 2;
    ctx.imageSmoothingEnabled = false;

    /* sky */
    const sky = ctx.createLinearGradient(0, 0, 0, h);
    sky.addColorStop(0, '#07060d');
    sky.addColorStop(0.38, '#160d24');
    sky.addColorStop(0.72, '#1c1029');
    sky.addColorStop(1, '#08060d');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    /* distant stars / dust in the dark */
    ctx.globalAlpha = 0.5;
    for (let i = 0; i < 26; i++) {
      const x = (i * 73 + 31) % w;
      const y = (i * 37 + 11) % 122;
      const flicker = 0.35 + 0.65 * Math.abs(Math.sin(time * 0.7 + i * 1.7));
      ctx.fillStyle = `rgba(196,173,255,${0.12 + flicker * 0.28})`;
      ctx.fillRect(x, y, 1, 1);
    }
    ctx.globalAlpha = 1;

    /* far arches */
    ctx.save();
    ctx.translate(px * 0.35, py * 0.3);
    this.arch(38, 30, 76, 158, '#160f23', '#241735');
    this.arch(188, 18, 104, 172, '#120c1d', '#2a1a3e');
    this.arch(346, 34, 82, 156, '#140e20', '#241735');
    ctx.restore();

    /* moon window */
    ctx.save();
    ctx.translate(px * 0.55, py * 0.4);
    const wx = 214;
    const wy = 38;
    const ww = 52;
    const wh = 84;
    ctx.fillStyle = '#0b0813';
    ctx.fillRect(wx - 6, wy - 6, ww + 12, wh + 12);
    const moon = ctx.createLinearGradient(0, wy, 0, wy + wh);
    moon.addColorStop(0, 'rgba(210,193,255,0.34)');
    moon.addColorStop(0.55, 'rgba(136,106,196,0.16)');
    moon.addColorStop(1, 'rgba(72,49,115,0.03)');
    ctx.fillStyle = moon;
    ctx.fillRect(wx, wy, ww, wh);
    ctx.fillStyle = 'rgba(7,5,13,0.82)';
    for (let x = wx + 8; x < wx + ww; x += 10) ctx.fillRect(x, wy, 2, wh);
    for (let y = wy + 9; y < wy + wh; y += 14) ctx.fillRect(wx, y, ww, 2);
    ctx.fillStyle = 'rgba(188,160,255,0.12)';
    ctx.fillRect(wx + 9, wy + 10, 9, 5);
    ctx.fillRect(wx + 30, wy + 33, 8, 4);
    ctx.restore();

    /* moon shafts */
    const shaft = ctx.createLinearGradient(wx, wy, wx + 18, 240);
    shaft.addColorStop(0, 'rgba(190,164,255,0.075)');
    shaft.addColorStop(0.55, 'rgba(160,130,230,0.035)');
    shaft.addColorStop(1, 'rgba(160,130,230,0)');
    ctx.fillStyle = shaft;
    ctx.beginPath();
    ctx.moveTo(wx + 2, wy + 6);
    ctx.lineTo(wx + ww - 2, wy + 6);
    ctx.lineTo(wx + ww + 54, 238);
    ctx.lineTo(wx - 34, 238);
    ctx.closePath();
    ctx.fill();

    /* back wall bricks */
    ctx.save();
    ctx.translate(px * 0.5, py * 0.45);
    this.brickWall(0, 46, w, 154, '#1c1028', '#241531');
    ctx.fillStyle = 'rgba(8,6,13,0.45)';
    ctx.fillRect(0, 46, w, 18);
    ctx.restore();

    /* columns */
    ctx.save();
    ctx.translate(px * 0.75, py * 0.55);
    this.column(56, 34, 202, 26);
    this.column(398, 42, 204, 24);
    this.column(132, 92, 202, 13, true);
    this.column(334, 92, 202, 13, true);
    ctx.restore();

    /* hanging vines */
    ctx.save();
    ctx.translate(px * 0.8, 0);
    ctx.fillStyle = 'rgba(63,46,85,0.8)';
    for (const [x, len] of [[22, 44], [30, 28], [151, 52], [161, 36], [372, 47], [383, 25], [452, 62]]) {
      ctx.fillRect(x, 0, 2, len);
      for (let y = 12; y < len; y += 13) {
        ctx.fillRect(x - 2, y, 2, 3);
        ctx.fillRect(x + 2, y + 6, 2, 3);
      }
    }
    ctx.restore();

    /* floor */
    const floor = ctx.createLinearGradient(0, 198, 0, h);
    floor.addColorStop(0, '#221428');
    floor.addColorStop(0.35, '#1a0f20');
    floor.addColorStop(1, '#07050b');
    ctx.fillStyle = floor;
    ctx.fillRect(0, 198, w, h - 198);

    ctx.save();
    ctx.translate(px * 0.25, 0);
    ctx.strokeStyle = 'rgba(94,66,120,0.2)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const x = i * 48;
      ctx.beginPath();
      ctx.moveTo(x, 198);
      ctx.lineTo(x - 26 + i * 5, h);
      ctx.stroke();
    }
    for (let i = 0; i < 6; i++) {
      const y = 206 + i * 12;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(7,5,11,0.6)';
    for (let i = 0; i < 8; i++) {
      const x = (i * 59 + 17) % w;
      const y = 202 + ((i * 31) % 55);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + 8, y + 5);
      ctx.lineTo(x + 4, y + 9);
      ctx.stroke();
    }
    ctx.restore();

    /* rubble silhouettes at the bottom */
    ctx.fillStyle = '#0a0710';
    ctx.fillRect(0, 250, w, 20);
    ctx.fillRect(10, 244, 36, 8);
    ctx.fillRect(56, 247, 22, 5);
    ctx.fillRect(300, 246, 44, 6);
    ctx.fillRect(444, 242, 26, 10);

    /* glowing flowers */
    ctx.save();
    ctx.translate(px * 0.18, 0);
    this.flower(356, 224, 1.15, time);
    this.flower(382, 236, 0.85, time + 1.1);
    this.flower(338, 242, 0.7, time + 2.3);
    this.flower(414, 228, 0.65, time + 0.6);
    this.flower(103, 238, 0.55, time + 1.8);
    ctx.restore();

    /* dust motes */
    for (const dot of this.dust) {
      const flicker = 0.55 + 0.45 * Math.sin(time * 0.9 + dot.phase);
      ctx.fillStyle = `rgba(203,187,255,${dot.alpha * flicker})`;
      ctx.fillRect(Math.round(dot.x), Math.round(dot.y), dot.size, dot.size);
    }

    /* fireflies near flowers */
    for (const fly of this.fireflies) {
      const x = fly.x + Math.sin(time * fly.speed + fly.phase) * fly.radius;
      const y = fly.y + Math.cos(time * fly.speed * 0.8 + fly.phase) * (fly.radius * 0.5);
      const alpha = 0.35 + 0.35 * Math.sin(time * 1.4 + fly.phase);
      ctx.fillStyle = `rgba(255,215,94,${Math.max(0, alpha)})`;
      ctx.fillRect(Math.round(x), Math.round(y), 2, 2);
    }

    /* leaves */
    for (const leaf of this.leaves) {
      const wobble = Math.sin(time * 1.3 + leaf.phase) * 2;
      ctx.fillStyle = `rgba(166,43,62,${leaf.alpha})`;
      ctx.fillRect(Math.round(leaf.x), Math.round(leaf.y + wobble), leaf.size, leaf.size);
      ctx.fillStyle = `rgba(224,81,94,${leaf.alpha * 0.55})`;
      ctx.fillRect(Math.round(leaf.x) + 1, Math.round(leaf.y + wobble) - 1, 1, 1);
    }

    /* darkness at the edges */
    const bottomFade = ctx.createLinearGradient(0, 226, 0, h);
    bottomFade.addColorStop(0, 'rgba(5,4,9,0)');
    bottomFade.addColorStop(1, 'rgba(5,4,9,0.88)');
    ctx.fillStyle = bottomFade;
    ctx.fillRect(0, 226, w, h - 226);
  }

  brickWall(x, y, w, h, base, line) {
    const ctx = this.ctx;
    ctx.fillStyle = base;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = line;
    for (let row = 0; row < Math.ceil(h / 12); row++) {
      const by = y + row * 12;
      ctx.fillRect(x, by, w, 1);
      const offset = row % 2 === 0 ? 0 : 15;
      for (let bx = x - offset; bx < x + w; bx += 30) ctx.fillRect(bx, by, 1, 12);
    }
    ctx.fillStyle = 'rgba(9,6,15,0.3)';
    for (let row = 1; row < Math.ceil(h / 12); row += 2) {
      for (let bx = 0; bx < w; bx += 60) ctx.fillRect(x + bx + 7, y + row * 12 + 4, 12, 3);
    }
  }

  arch(x, y, w, h, base, edge) {
    const ctx = this.ctx;
    ctx.fillStyle = base;
    ctx.fillRect(x, y + 16, w, h - 16);
    ctx.fillStyle = edge;
    ctx.fillRect(x + 6, y + 10, w - 12, h - 10);
    ctx.fillStyle = base;
    ctx.fillRect(x + 13, y + 18, w - 26, h - 20);
    ctx.fillStyle = 'rgba(6,4,10,0.78)';
    ctx.fillRect(x + 17, y + 24, w - 34, h - 28);
    ctx.fillStyle = 'rgba(169,139,255,0.06)';
    ctx.fillRect(x + 17, y + 24, 2, h - 28);
  }

  column(x, y, bottom, w, small = false) {
    const ctx = this.ctx;
    ctx.fillStyle = '#120c1d';
    ctx.fillRect(x, y, w, bottom - y);
    ctx.fillStyle = '#2a1a3e';
    ctx.fillRect(x + 3, y, w - 6, bottom - y);
    ctx.fillStyle = '#1a1028';
    ctx.fillRect(x + 6, y + 4, 3, bottom - y - 8);
    ctx.fillStyle = '#362248';
    ctx.fillRect(x + 10, y + 4, 1, bottom - y - 9);
    if (!small) {
      ctx.fillStyle = '#3a2750';
      ctx.fillRect(x - 3, y, w + 6, 5);
      ctx.fillRect(x - 4, bottom - 5, w + 8, 5);
      ctx.fillStyle = '#150d20';
      ctx.fillRect(x - 3, y + 5, w + 6, 2);
    }
  }

  flower(x, y, scale, time) {
    const ctx = this.ctx;
    const sway = Math.sin(time * 1.1 + x) * 1.2;
    const h = 16 * scale;
    const stemX = Math.round(x + sway);
    const baseY = Math.round(y);
    const glow = ctx.createRadialGradient(stemX, baseY - h, 0, stemX, baseY - h, 22 * scale);
    glow.addColorStop(0, 'rgba(255,215,94,0.22)');
    glow.addColorStop(0.45, 'rgba(255,179,71,0.08)');
    glow.addColorStop(1, 'rgba(255,179,71,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(stemX - 24 * scale, baseY - h - 24 * scale, 48 * scale, 48 * scale);

    ctx.fillStyle = '#4c7a3b';
    ctx.fillRect(stemX, Math.round(baseY - h), 1, Math.round(h));
    ctx.fillRect(stemX - Math.round(4 * scale), Math.round(baseY - h * 0.55), Math.round(4 * scale), 1);
    ctx.fillStyle = '#3d6330';
    ctx.fillRect(stemX + 1, Math.round(baseY - h * 0.35), Math.round(3 * scale), 1);

    const cy = Math.round(baseY - h);
    const cx = stemX;
    ctx.fillStyle = '#ffcf5e';
    ctx.fillRect(cx - Math.round(4 * scale), cy - Math.round(2 * scale), Math.round(8 * scale), Math.round(4 * scale));
    ctx.fillRect(cx - Math.round(2 * scale), cy - Math.round(4 * scale), Math.round(4 * scale), Math.round(8 * scale));
    ctx.fillStyle = '#ffe89a';
    ctx.fillRect(cx - Math.round(2 * scale), cy - Math.round(2 * scale), Math.round(3 * scale), Math.round(3 * scale));
    ctx.fillStyle = '#b57a1c';
    ctx.fillRect(cx, cy, 1, 1);
  }
}

import { getLang } from './i18n.js';
import { getSettings, setSetting } from './settings.js';
import { audio } from './audio.js';
import { DEFAULT_PACK, packLines, packText } from './packs.js';
import { t } from './i18n.js';

const SOUL_COLORS = {
  red: '#ff3b47',
  cyan: '#5ce1e6',
  lime: '#9bff6b',
  gold: '#ffd75e'
};

const BATTLE_BOX = { x: 116, y: 158, w: 248, h: 88 };
const BATTLE_INNER = { x: BATTLE_BOX.x + 6, y: BATTLE_BOX.y + 6, w: BATTLE_BOX.w - 12, h: BATTLE_BOX.h - 12 };
const ROOM_BOUNDS = { x1: 46, x2: 432, y1: 166, y2: 250 };

export class SoulTrial {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.options = options;
    this.width = 480;
    this.height = 270;
    this.running = false;
    this.paused = false;
    this.time = 0;
    this.last = 0;
    this.mode = 'explore';
    this.pack = DEFAULT_PACK;
    this.palette = DEFAULT_PACK.palette;
    this.lines = packLines(DEFAULT_PACK, getLang());
    this.npcName = 'MIMO';
    this.roomName = 'RUINS // ROOM 01';
    this.input = { up: false, down: false, left: false, right: false };
    this.keys = new Set();
    this.player = { x: 366, y: 210, facing: 'left', walk: 0, moving: false };
    this.npc = { x: 168, y: 192, bob: 0 };
    this.hp = 20;
    this.maxHp = 20;
    this.projectiles = [];
    this.sparkles = [];
    this.dust = [];
    this.leaves = [];
    this.dialogueQueue = [];
    this.dialogueFull = '';
    this.dialogueShown = 0;
    this.dialogueSpeaker = '';
    this.dialogueDone = null;
    this.dialogueActive = false;
    this.cleared = Boolean(getSettings().cleared);
    this.shake = 0;
    this.hitFlash = 0;
    this.invuln = 0;
    this.dash = 0;
    this.dashCooldown = 0;
    this.battleTimer = 15;
    this.spawnTimer = 0;
    this.spawnInterval = 0.42;
    this.battleActive = false;
    this.raf = null;
    this.timeoutIds = [];
    this.soulColor = SOUL_COLORS[getSettings().soul] || SOUL_COLORS.red;
    this.bound = false;

    this.dom = {
      dialogueBox: document.getElementById('dialogueBox'),
      dialogueName: document.getElementById('dialogueName'),
      dialogueText: document.getElementById('dialogueText'),
      dialogueNext: document.getElementById('dialogueNext'),
      battleBanner: document.getElementById('battleBanner'),
      battleTimer: document.getElementById('battleTimer'),
      hpFill: document.getElementById('hpFill'),
      hpText: document.getElementById('hpText'),
      hudPackName: document.getElementById('hudPackName'),
      pauseOverlay: document.getElementById('pauseOverlay'),
      demoRoom: document.getElementById('demoRoom'),
      demoStage: document.getElementById('demoStage'),
      gameTouch: document.getElementById('gameTouch'),
      rotateHint: document.getElementById('rotateHint')
    };
    this.bind();
  }

  bind() {
    if (this.bound) return;
    this.bound = true;
    this.onKeyDown = (event) => {
      if (!this.running) return;
      const tag = event.target?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      const key = event.key;
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' ', 'Spacebar'].includes(key)) event.preventDefault();
      if (key === 'ArrowUp' || key === 'w' || key === 'W' || key === 'ц' || key === 'Ц') this.input.up = true;
      else if (key === 'ArrowDown' || key === 's' || key === 'S' || key === 'ы' || key === 'Ы') this.input.down = true;
      else if (key === 'ArrowLeft' || key === 'a' || key === 'A' || key === 'ф' || key === 'Ф') this.input.left = true;
      else if (key === 'ArrowRight' || key === 'd' || key === 'D' || key === 'в' || key === 'В') this.input.right = true;
      else if (key === 'z' || key === 'Z' || key === 'Enter' || key === ' ') {
        if (!event.repeat) this.press('a');
      } else if (key === 'x' || key === 'X' || key === 'Escape' || key === 'я' || key === 'Я' || key === 'ч' || key === 'Ч') {
        if (!event.repeat) this.press('b');
      }
    };
    this.onKeyUp = (event) => {
      const key = event.key;
      if (key === 'ArrowUp' || key === 'w' || key === 'W' || key === 'ц' || key === 'Ц') this.input.up = false;
      else if (key === 'ArrowDown' || key === 's' || key === 'S' || key === 'ы' || key === 'Ы') this.input.down = false;
      else if (key === 'ArrowLeft' || key === 'a' || key === 'A' || key === 'ф' || key === 'Ф') this.input.left = false;
      else if (key === 'ArrowRight' || key === 'd' || key === 'D' || key === 'в' || key === 'В') this.input.right = false;
    };
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', () => { this.input.up = this.input.down = this.input.left = this.input.right = false; });

    if (this.dom.gameTouch) {
      this.dom.gameTouch.querySelectorAll('[data-dir]').forEach((button) => {
        const dir = button.dataset.dir;
        const press = (event) => {
          event.preventDefault();
          this.input[dir] = true;
          button.classList.add('is-down');
          if (navigator.vibrate) navigator.vibrate(6);
        };
        const release = () => {
          this.input[dir] = false;
          button.classList.remove('is-down');
        };
        button.addEventListener('pointerdown', press);
        button.addEventListener('pointerup', release);
        button.addEventListener('pointercancel', release);
        button.addEventListener('pointerleave', release);
        button.addEventListener('contextmenu', (event) => event.preventDefault());
      });
      this.dom.gameTouch.querySelectorAll('[data-act]').forEach((button) => {
        button.addEventListener('pointerdown', (event) => {
          event.preventDefault();
          button.classList.add('is-down');
          this.press(button.dataset.act);
          if (navigator.vibrate) navigator.vibrate(8);
        });
        const release = () => button.classList.remove('is-down');
        button.addEventListener('pointerup', release);
        button.addEventListener('pointercancel', release);
        button.addEventListener('pointerleave', release);
      });
    }

    document.getElementById('resumeBtn')?.addEventListener('click', () => { audio.play('select'); this.resume(); });
    document.getElementById('pauseQuit')?.addEventListener('click', () => { audio.play('select'); this.options.onQuit?.(); });
    document.getElementById('pauseSettings')?.addEventListener('click', () => {
      audio.play('select');
      this.hidePauseOverlay();
      this.options.onSettings?.();
    });

    this.onResize = () => this.updateRotateHint();
    window.addEventListener('resize', this.onResize);
    this.updateRotateHint();
  }

  updateRotateHint() {
    if (!this.dom.rotateHint) return;
    const portrait = window.innerHeight > window.innerWidth && window.innerWidth < 900;
    this.dom.rotateHint.classList.toggle('is-portrait', portrait);
  }

  start(pack = DEFAULT_PACK) {
    this.pack = pack || DEFAULT_PACK;
    this.palette = { ...DEFAULT_PACK.palette, ...(pack.palette || {}) };
    this.lines = packLines(this.pack, getLang());
    this.npcName = packText(pack.npcName, getLang()) || 'MIMO';
    this.roomName = packText(pack.roomName, getLang()) || 'RUINS // ROOM 01';
    this.soulColor = SOUL_COLORS[getSettings().soul] || SOUL_COLORS.red;
    this.cleared = Boolean(getSettings().cleared);
    this.mode = 'explore';
    this.paused = false;
    this.hp = 20;
    this.maxHp = 20;
    this.player = { x: 366, y: 210, facing: 'left', walk: 0, moving: false };
    this.npc = { x: 168, y: 192, bob: 0 };
    this.projectiles = [];
    this.sparkles = [];
    this.battleActive = false;
    this.dialogueQueue = [];
    this.dialogueActive = false;
    this.shake = 0;
    this.hitFlash = 0;
    this.invuln = 0;
    this.dash = 0;
    this.dashCooldown = 0;
    this.input.up = this.input.down = this.input.left = this.input.right = false;
    this.time = 0;
    this.spawnTimer = 0;
    this.running = true;
    this.hideDialogue();
    this.hidePauseOverlay();
    this.dom.battleBanner?.classList.add('is-hidden');
    this.updateHud();
    if (this.dom.hudPackName) this.dom.hudPackName.textContent = this.pack.name || 'DEFAULT SOUL';
    if (this.dom.demoRoom) this.dom.demoRoom.textContent = this.roomName;
    this.seedAmbient();
    audio.setTheme('game', this.pack.tempo || 1);

    this.timeoutIds.forEach(clearTimeout);
    this.timeoutIds = [];
    this.timeoutIds.push(setTimeout(() => {
      if (!this.running) return;
      this.showDialogue(this.lines.intro, {
        speaker: 'RUINS',
        onDone: () => { this.mode = 'explore'; }
      });
    }, 420));

    if (!this.raf) {
      this.last = performance.now();
      this.raf = requestAnimationFrame((now) => this.loop(now));
    }
  }

  stop() {
    this.running = false;
    this.paused = false;
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = null;
    this.timeoutIds.forEach(clearTimeout);
    this.timeoutIds = [];
    this.hideDialogue();
    this.hidePauseOverlay();
    this.dom.battleBanner?.classList.add('is-hidden');
    this.input.up = this.input.down = this.input.left = this.input.right = false;
    this.mode = 'explore';
  }

  pause() {
    if (!this.running || this.paused) return;
    this.paused = true;
    this.input.up = this.input.down = this.input.left = this.input.right = false;
    this.dom.pauseOverlay?.classList.remove('is-hidden');
  }

  resume() {
    if (!this.running) return;
    this.paused = false;
    this.dom.pauseOverlay?.classList.add('is-hidden');
    this.last = performance.now();
  }

  hidePauseOverlay() {
    this.dom.pauseOverlay?.classList.add('is-hidden');
  }

  hideDialogue() {
    this.dialogueActive = false;
    this.dom.dialogueBox?.classList.add('is-hidden');
  }

  loop(now) {
    if (!this.running) { this.raf = null; return; }
    const dt = Math.min(0.05, Math.max(0, (now - this.last) / 1000));
    this.last = now;
    if (!this.paused) {
      this.time += dt;
      this.update(dt);
    }
    this.draw();
    this.raf = requestAnimationFrame((next) => this.loop(next));
  }

  update(dt) {
    this.updateDialogue(dt);
    this.updateSparkles(dt);
    this.updateAmbient(dt);
    if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 2.6);
    if (this.hitFlash > 0) this.hitFlash = Math.max(0, this.hitFlash - dt * 3);
    if (this.invuln > 0) this.invuln = Math.max(0, this.invuln - dt);
    if (this.dash > 0) this.dash = Math.max(0, this.dash - dt);
    if (this.dashCooldown > 0) this.dashCooldown = Math.max(0, this.dashCooldown - dt);
    this.npc.bob = Math.sin(this.time * 2.1) * 2;

    if (this.mode === 'dialogue') return;
    if (this.mode === 'battle') this.updateBattle(dt);
    else this.updateExplore(dt);
  }

  updateExplore(dt) {
    let dx = 0;
    let dy = 0;
    if (this.input.left) dx -= 1;
    if (this.input.right) dx += 1;
    if (this.input.up) dy -= 1;
    if (this.input.down) dy += 1;
    const moving = dx !== 0 || dy !== 0;
    this.player.moving = moving;
    if (moving) {
      const length = Math.hypot(dx, dy) || 1;
      const speed = 82 * (this.pack.speed || 1);
      this.player.x += (dx / length) * speed * dt;
      this.player.y += (dy / length) * speed * dt;
      this.player.x = Math.max(ROOM_BOUNDS.x1, Math.min(ROOM_BOUNDS.x2, this.player.x));
      this.player.y = Math.max(ROOM_BOUNDS.y1, Math.min(ROOM_BOUNDS.y2, this.player.y));
      this.player.walk += dt * 11;
      if (Math.abs(dx) > Math.abs(dy)) this.player.facing = dx > 0 ? 'right' : 'left';
      else this.player.facing = dy > 0 ? 'down' : 'up';
    } else {
      this.player.walk = 0;
    }
  }

  updateBattle(dt) {
    this.battleTimer = Math.max(0, this.battleTimer - dt);
    if (this.dom.battleTimer) this.dom.battleTimer.textContent = this.battleTimer.toFixed(1);
    if (this.battleTimer <= 0) { this.winBattle(); return; }

    const progress = 1 - this.battleTimer / 15;
    this.spawnInterval = 0.44 - progress * 0.2;
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnTimer = this.spawnInterval;
      this.spawnStar(progress);
    }

    let dx = 0;
    let dy = 0;
    if (this.input.left) dx -= 1;
    if (this.input.right) dx += 1;
    if (this.input.up) dy -= 1;
    if (this.input.down) dy += 1;
    if (dx || dy) {
      const length = Math.hypot(dx, dy) || 1;
      const speed = (112 + (this.dash > 0 ? 130 : 0)) * (this.pack.speed || 1);
      this.soulX = Math.max(BATTLE_INNER.x + 4, Math.min(BATTLE_INNER.x + BATTLE_INNER.w - 4, (this.soulX ?? 236) + (dx / length) * speed * dt));
      this.soulY = Math.max(BATTLE_INNER.y + 4, Math.min(BATTLE_INNER.y + BATTLE_INNER.h - 4, (this.soulY ?? 200) + (dy / length) * speed * dt));
    }
    this.soulX ??= 236;
    this.soulY ??= 200;

    const soul = { x: this.soulX - 4, y: this.soulY - 4, w: 8, h: 8 };
    for (const star of this.projectiles) {
      star.x += star.vx * dt;
      star.y += star.vy * dt;
      star.phase += dt * 5;
      if (star.wave) star.x += Math.sin(star.phase) * star.wave * dt;
      star.life -= dt;
      if (this.overlaps(soul, { x: star.x - 2, y: star.y - 2, w: 5, h: 5 }) && this.invuln <= 0) {
        this.takeHit(star);
      }
    }
    this.projectiles = this.projectiles.filter((star) => star.life > 0 && star.y < BATTLE_BOX.y + BATTLE_BOX.h + 12 && star.y > BATTLE_BOX.y - 14 && star.x > BATTLE_BOX.x - 16 && star.x < BATTLE_BOX.x + BATTLE_BOX.w + 16);
  }

  overlaps(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  spawnStar(progress) {
    const side = progress > 0.45 && Math.random() > 0.62;
    if (side) {
      const fromLeft = Math.random() > 0.5;
      this.projectiles.push({
        x: fromLeft ? BATTLE_BOX.x - 8 : BATTLE_BOX.x + BATTLE_BOX.w + 8,
        y: BATTLE_INNER.y + 8 + Math.random() * (BATTLE_INNER.h - 16),
        vx: (fromLeft ? 1 : -1) * (44 + Math.random() * 30),
        vy: (Math.random() - 0.5) * 18,
        wave: 0,
        phase: Math.random() * 6,
        life: 6,
        color: Math.random() > 0.5 ? '#6fe7e8' : '#ffd75e'
      });
    } else {
      this.projectiles.push({
        x: BATTLE_INNER.x + 8 + Math.random() * (BATTLE_INNER.w - 16),
        y: BATTLE_BOX.y - 6,
        vx: (Math.random() - 0.5) * 10,
        vy: 54 + Math.random() * 58 + progress * 15,
        wave: 8 + Math.random() * 12,
        phase: Math.random() * 6,
        life: 6,
        color: Math.random() > 0.55 ? '#6fe7e8' : '#ffd75e'
      });
    }
  }

  takeHit(star) {
    this.hp = Math.max(0, this.hp - 2);
    this.invuln = 1.1;
    this.shake = 0.38;
    this.hitFlash = 0.6;
    this.updateHud();
    audio.play('hit');
    if (navigator.vibrate) navigator.vibrate([25, 30, 25]);
    this.sparkles.push(...Array.from({ length: 6 }, () => ({
      x: this.soulX + (Math.random() - 0.5) * 10,
      y: this.soulY + (Math.random() - 0.5) * 10,
      vx: (Math.random() - 0.5) * 60,
      vy: (Math.random() - 0.5) * 60,
      life: 0.4,
      max: 0.4,
      color: '#ff3b47',
      size: 2
    })));
    if (this.hp <= 0) this.loseBattle();
  }

  winBattle() {
    if (!this.battleActive) return;
    this.battleActive = false;
    this.mode = 'dialogue';
    this.projectiles = [];
    this.dom.battleBanner?.classList.add('is-hidden');
    audio.play('clear');
    this.spawnBurst(240, 130, 26, '#ffd75e');
    this.showDialogue(this.lines.win, {
      speaker: this.npcName,
      onDone: () => {
        this.cleared = true;
        setSetting('cleared', true);
        this.soulColor = SOUL_COLORS[getSettings().soul] || SOUL_COLORS.red;
        this.mode = 'explore';
        this.options.onClear?.();
      }
    });
  }

  loseBattle() {
    this.battleActive = false;
    this.mode = 'dialogue';
    this.projectiles = [];
    this.dom.battleBanner?.classList.add('is-hidden');
    this.showDialogue(this.lines.lose, {
      speaker: this.npcName,
      onDone: () => {
        this.hp = this.maxHp;
        this.updateHud();
        this.mode = 'explore';
        this.player.x = this.npc.x + 36;
        this.player.y = this.npc.y + 4;
      }
    });
  }

  startBattle() {
    this.mode = 'battle';
    this.battleActive = true;
    this.battleTimer = 15;
    this.spawnTimer = 0.5;
    this.projectiles = [];
    this.soulX = BATTLE_BOX.x + BATTLE_BOX.w / 2;
    this.soulY = BATTLE_BOX.y + BATTLE_BOX.h - 18;
    this.hp = this.maxHp;
    this.invuln = 1.2;
    this.dashCooldown = 0;
    this.updateHud();
    this.dom.battleBanner?.classList.remove('is-hidden');
    if (this.dom.battleTimer) this.dom.battleTimer.textContent = '15.0';
    audio.play('select');
  }

  interact() {
    const dx = this.player.x - this.npc.x;
    const dy = this.player.y - this.npc.y;
    if (Math.hypot(dx, dy) < 36) {
      const opener = this.cleared ? this.lines.cleared : this.lines.npc;
      this.showDialogue(opener, {
        speaker: this.npcName,
        onDone: () => this.startBattle()
      });
      return;
    }
    if (Math.hypot(this.player.x - 82, this.player.y - 216) < 32) {
      this.hp = this.maxHp;
      this.updateHud();
      audio.play('heal');
      this.spawnBurst(82, 208, 14, '#ffd75e');
      this.showDialogue(this.lines.flower, { speaker: 'RUINS' });
      return;
    }
    if (this.player.x > 404 && this.player.y < 198) {
      this.showDialogue(this.lines.door, { speaker: 'RUINS' });
      return;
    }
    audio.play('move');
  }

  press(action) {
    if (!this.running) return;
    audio.unlock();
    if (this.paused) {
      if (action === 'a') this.resume();
      return;
    }
    if (action === 'b') {
      audio.play('back');
      if (this.mode === 'dialogue') {
        this.hideDialogue();
        this.dialogueQueue = [];
        const done = this.dialogueDone;
        this.dialogueDone = null;
        this.mode = 'explore';
        done?.();
      } else {
        this.pause();
      }
      return;
    }
    if (this.mode === 'dialogue') {
      this.advanceDialogue();
      return;
    }
    if (this.mode === 'battle') {
      audio.play('select');
      if (this.dashCooldown <= 0) {
        this.dash = 0.16;
        this.dashCooldown = 1.4;
        this.invuln = Math.max(this.invuln, 0.25);
      }
      return;
    }
    if (this.mode === 'explore') {
      audio.play('select');
      this.interact();
    }
  }

  showDialogue(lines, { speaker = this.npcName, onDone = null } = {}) {
    if (!Array.isArray(lines) || lines.length === 0) { onDone?.(); return; }
    this.mode = 'dialogue';
    this.dialogueQueue = [...lines];
    this.dialogueSpeaker = speaker;
    this.dialogueDone = onDone;
    this.dialogueActive = true;
    this.dom.dialogueBox?.classList.remove('is-hidden');
    if (this.dom.dialogueName) this.dom.dialogueName.textContent = speaker;
    this.nextDialogue();
  }

  nextDialogue() {
    if (this.dialogueQueue.length === 0) {
      this.hideDialogue();
      const done = this.dialogueDone;
      this.dialogueDone = null;
      if (this.mode === 'dialogue') this.mode = 'explore';
      done?.();
      return;
    }
    this.dialogueFull = this.dialogueQueue.shift();
    this.dialogueShown = 0;
    if (this.dom.dialogueText) this.dom.dialogueText.textContent = '';
    if (this.dom.dialogueNext) this.dom.dialogueNext.classList.add('is-hidden');
  }

  updateDialogue(dt) {
    if (!this.dialogueActive || this.mode !== 'dialogue') return;
    if (this.dialogueShown < this.dialogueFull.length) {
      const before = Math.floor(this.dialogueShown);
      this.dialogueShown = Math.min(this.dialogueFull.length, this.dialogueShown + dt * 52);
      const after = Math.floor(this.dialogueShown);
      if (after !== before && this.dom.dialogueText) {
        this.dom.dialogueText.textContent = this.dialogueFull.slice(0, after);
        if (after % 3 === 0) audio.play('type');
      }
      if (this.dialogueShown >= this.dialogueFull.length) this.dom.dialogueNext?.classList.remove('is-hidden');
    }
  }

  advanceDialogue() {
    if (!this.dialogueActive) return;
    if (this.dialogueShown < this.dialogueFull.length) {
      this.dialogueShown = this.dialogueFull.length;
      if (this.dom.dialogueText) this.dom.dialogueText.textContent = this.dialogueFull;
      this.dom.dialogueNext?.classList.remove('is-hidden');
      return;
    }
    audio.play('select');
    this.nextDialogue();
  }

  updateHud() {
    const pct = Math.max(0, Math.min(100, (this.hp / this.maxHp) * 100));
    if (this.dom.hpFill) {
      this.dom.hpFill.style.width = `${pct}%`;
      this.dom.hpFill.style.background = pct > 45 ? 'var(--gold)' : 'var(--red)';
    }
    if (this.dom.hpText) this.dom.hpText.textContent = `${this.hp} / ${this.maxHp}`;
  }

  seedAmbient() {
    const rand = () => Math.random();
    this.dust = Array.from({ length: 22 }, () => ({
      x: 30 + rand() * 420,
      y: 120 + rand() * 140,
      speed: 4 + rand() * 10,
      drift: (rand() - 0.5) * 4,
      phase: rand() * Math.PI * 2,
      size: rand() > 0.75 ? 2 : 1,
      alpha: 0.15 + rand() * 0.35
    }));
    this.leaves = Array.from({ length: 7 }, () => ({
      x: rand() * 480,
      y: 30 + rand() * 210,
      speed: 8 + rand() * 14,
      drift: (rand() - 0.5) * 7,
      phase: rand() * Math.PI * 2,
      size: 2 + Math.floor(rand() * 2),
      alpha: 0.3 + rand() * 0.4
    }));
  }

  updateAmbient(dt) {
    for (const dot of this.dust) {
      dot.y -= dot.speed * dt;
      dot.x += Math.sin(this.time * 0.5 + dot.phase) * dot.drift * dt;
      if (dot.y < 120) { dot.y = 262; dot.x = 30 + Math.random() * 420; }
    }
    for (const leaf of this.leaves) {
      leaf.x += leaf.speed * dt;
      leaf.y += Math.sin(this.time + leaf.phase) * 5 * dt;
      if (leaf.x > 492) { leaf.x = -12; leaf.y = 30 + Math.random() * 210; }
    }
  }

  spawnBurst(x, y, count, color) {
    for (let i = 0; i < count; i++) {
      const angle = (Math.PI * 2 * i) / count + Math.random() * 0.3;
      const speed = 18 + Math.random() * 46;
      this.sparkles.push({
        x, y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 8,
        life: 0.7 + Math.random() * 0.5,
        max: 1.2,
        color,
        size: Math.random() > 0.5 ? 2 : 1
      });
    }
  }

  updateSparkles(dt) {
    for (const spark of this.sparkles) {
      spark.x += spark.vx * dt;
      spark.y += spark.vy * dt;
      spark.vy += 40 * dt;
      spark.life -= dt;
    }
    this.sparkles = this.sparkles.filter((spark) => spark.life > 0);
  }

  /* ------------------------------------------------------------------ */
  /* rendering                                                          */
  /* ------------------------------------------------------------------ */

  draw() {
    const ctx = this.ctx;
    const p = this.palette;
    const settings = getSettings();
    ctx.imageSmoothingEnabled = false;
    ctx.save();
    if (settings.shake && this.shake > 0) {
      ctx.translate(Math.round((Math.random() - 0.5) * 6 * this.shake), Math.round((Math.random() - 0.5) * 6 * this.shake));
    }

    this.drawRoom(ctx, p);

    if (this.mode === 'battle') {
      this.drawBattle(ctx, p);
    } else {
      this.drawEntities(ctx, p);
    }

    for (const spark of this.sparkles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, spark.life / (spark.max || 1)));
      ctx.fillStyle = spark.color;
      ctx.fillRect(Math.round(spark.x), Math.round(spark.y), spark.size, spark.size);
    }
    ctx.globalAlpha = 1;

    if (this.hitFlash > 0) {
      ctx.fillStyle = `rgba(255,45,60,${this.hitFlash * 0.28})`;
      ctx.fillRect(0, 0, 480, 270);
    }

    ctx.restore();
  }

  drawRoom(ctx, p) {
    ctx.fillStyle = p.bg;
    ctx.fillRect(0, 0, 480, 270);

    /* back wall */
    ctx.fillStyle = p.wallDark;
    ctx.fillRect(0, 38, 480, 118);
    ctx.fillStyle = p.wall;
    ctx.fillRect(0, 52, 480, 100);
    ctx.fillStyle = p.wallLight;
    ctx.fillRect(0, 52, 480, 2);

    /* bricks */
    ctx.fillStyle = p.brick;
    for (let row = 0; row < 7; row++) {
      const y = 56 + row * 14;
      ctx.fillRect(0, y, 480, 1);
      const offset = row % 2 === 0 ? 0 : 17;
      for (let x = -offset; x < 480; x += 34) ctx.fillRect(x, y, 1, 14);
    }
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    for (let row = 0; row < 7; row += 2) {
      for (let x = 5; x < 480; x += 34) ctx.fillRect(x + (row % 2) * 17, 62 + row * 14, 12, 3);
    }

    /* window with moonlight */
    ctx.fillStyle = '#070510';
    ctx.fillRect(322, 66, 58, 58);
    const moon = ctx.createLinearGradient(0, 68, 0, 122);
    moon.addColorStop(0, 'rgba(205,188,255,0.28)');
    moon.addColorStop(1, 'rgba(120,94,180,0.03)');
    ctx.fillStyle = moon;
    ctx.fillRect(326, 70, 50, 50);
    ctx.fillStyle = 'rgba(7,5,13,0.8)';
    for (let x = 336; x < 376; x += 12) ctx.fillRect(x, 70, 2, 50);
    for (let y = 80; y < 120; y += 13) ctx.fillRect(326, y, 50, 2);

    /* pillars */
    this.drawPillar(ctx, p, 28, 36, 30, 120);
    this.drawPillar(ctx, p, 424, 36, 28, 120);

    /* door */
    ctx.fillStyle = p.door;
    ctx.fillRect(418, 110, 44, 58);
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(422, 114, 36, 54);
    ctx.fillStyle = p.doorGlow;
    ctx.globalAlpha = 0.35 + Math.sin(this.time * 2) * 0.1;
    ctx.fillRect(424, 116, 2, 52);
    ctx.globalAlpha = 1;
    ctx.fillStyle = p.brick;
    ctx.fillRect(412, 104, 56, 8);

    /* floor */
    const floor = ctx.createLinearGradient(0, 154, 0, 270);
    floor.addColorStop(0, p.floor);
    floor.addColorStop(1, p.floorDark);
    ctx.fillStyle = floor;
    ctx.fillRect(0, 154, 480, 116);
    ctx.fillStyle = p.floorLine;
    ctx.fillRect(0, 154, 480, 2);
    ctx.globalAlpha = 0.45;
    for (let i = 0; i <= 12; i++) {
      const x = i * 40;
      ctx.fillRect(x, 156, 1, 114);
    }
    for (let y = 170; y < 270; y += 18) ctx.fillRect(0, y, 480, 1);
    ctx.globalAlpha = 1;

    /* rug */
    ctx.fillStyle = 'rgba(255,215,94,0.06)';
    ctx.fillRect(140, 184, 200, 42);
    ctx.fillStyle = 'rgba(255,215,94,0.12)';
    ctx.fillRect(140, 184, 200, 2);
    ctx.fillRect(140, 224, 200, 2);

    /* flowers */
    this.drawFlower(ctx, p, 80, 224, 1.15);
    this.drawFlower(ctx, p, 96, 236, 0.8);
    this.drawFlower(ctx, p, 62, 238, 0.72);
    this.drawFlower(ctx, p, 406, 240, 0.55);

    /* ambient */
    for (const dot of this.dust) {
      ctx.globalAlpha = dot.alpha * (0.55 + 0.45 * Math.sin(this.time * 0.8 + dot.phase));
      ctx.fillStyle = p.ambient;
      ctx.fillRect(Math.round(dot.x), Math.round(dot.y), dot.size, dot.size);
    }
    ctx.globalAlpha = 1;
    for (const leaf of this.leaves) {
      ctx.fillStyle = `rgba(190,60,76,${leaf.alpha})`;
      ctx.fillRect(Math.round(leaf.x), Math.round(leaf.y), leaf.size, leaf.size);
    }

    /* bottom fade */
    const fade = ctx.createLinearGradient(0, 238, 0, 270);
    fade.addColorStop(0, 'rgba(4,3,8,0)');
    fade.addColorStop(1, 'rgba(4,3,8,0.5)');
    ctx.fillStyle = fade;
    ctx.fillRect(0, 238, 480, 32);
  }

  drawPillar(ctx, p, x, y, w, h) {
    ctx.fillStyle = p.wallDark;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = p.wallLight;
    ctx.fillRect(x + 3, y, w - 6, h);
    ctx.fillStyle = p.wall;
    ctx.fillRect(x + 6, y + 4, w - 12, h - 8);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(x + 6, y + 4, 3, h - 8);
    ctx.fillStyle = p.brick;
    ctx.fillRect(x - 3, y, w + 6, 5);
    ctx.fillRect(x - 4, y + h - 5, w + 8, 5);
  }

  drawEntities(ctx, p) {
    /* NPC shadow */
    ctx.fillStyle = 'rgba(0,0,0,0.32)';
    ctx.fillRect(this.npc.x - 9, 213, 20, 3);
    this.drawNpc(ctx, p, this.npc.x, this.npc.y + this.npc.bob);

    /* player shadow */
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.fillRect(this.player.x - 6, this.player.y + 10, 13, 3);
    this.drawPlayer(ctx, p, this.player);

    /* interaction hint */
    const nearNpc = Math.hypot(this.player.x - this.npc.x, this.player.y - this.npc.y) < 36;
    if (nearNpc && this.mode === 'explore') {
      const bob = Math.sin(this.time * 3) * 1.5;
      ctx.fillStyle = 'rgba(255,215,94,0.9)';
      ctx.fillRect(this.npc.x - 1, this.npc.y - 32 + bob, 6, 2);
      ctx.fillRect(this.npc.x + 1, this.npc.y - 29 + bob, 2, 2);
    }
  }

  drawNpc(ctx, p, x, y) {
    const bob = Math.sin(this.time * 2.1) * 1.4;
    const cy = y + bob;
    const glow = ctx.createRadialGradient(x, cy - 4, 0, x, cy - 4, 26);
    glow.addColorStop(0, 'rgba(240,234,255,0.12)');
    glow.addColorStop(1, 'rgba(240,234,255,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - 26, cy - 30, 52, 52);

    /* body */
    ctx.fillStyle = p.npc;
    ctx.fillRect(x - 9, cy - 14, 18, 18);
    ctx.fillRect(x - 7, cy + 4, 14, 3);
    ctx.fillRect(x - 5, cy + 7, 4, 2);
    ctx.fillRect(x + 2, cy + 7, 3, 2);
    /* wavy bottom */
    ctx.fillStyle = 'rgba(0,0,0,0.08)';
    ctx.fillRect(x - 7, cy + 4, 14, 1);
    /* eyes */
    ctx.fillStyle = '#241b33';
    ctx.fillRect(x - 5, cy - 8, 3, 3);
    ctx.fillRect(x + 3, cy - 8, 3, 3);
    ctx.fillStyle = '#fff';
    ctx.fillRect(x - 4, cy - 7, 1, 1);
    ctx.fillRect(x + 4, cy - 7, 1, 1);
    /* scarf */
    ctx.fillStyle = p.npcAccent;
    ctx.fillRect(x - 9, cy - 2, 18, 3);
    ctx.fillRect(x + 5, cy + 1, 4, 5);
    /* mouth */
    ctx.fillStyle = 'rgba(36,27,51,0.7)';
    ctx.fillRect(x - 1, cy - 3, 3, 1);
  }

  drawPlayer(ctx, p, player) {
    const x = Math.round(player.x);
    const y = Math.round(player.y);
    const moving = player.moving;
    const frame = Math.floor(player.walk) % 2;
    const legOffset = moving ? frame : 0;

    /* legs */
    ctx.fillStyle = '#1d1528';
    ctx.fillRect(x - 4, y + 5 + legOffset, 3, 5 - legOffset);
    ctx.fillRect(x + 1, y + 5 + (moving ? 1 - legOffset : 0), 3, 4);
    /* body */
    ctx.fillStyle = p.player;
    ctx.fillRect(x - 5, y - 3, 10, 9);
    /* scarf */
    ctx.fillStyle = p.playerAccent;
    ctx.fillRect(x - 5, y - 3, 10, 2);
    ctx.fillRect(x + 4, y - 1, 2, 5);
    /* head */
    ctx.fillStyle = '#f1c9a5';
    ctx.fillRect(x - 5, y - 12, 10, 8);
    /* hair */
    ctx.fillStyle = '#241b2b';
    ctx.fillRect(x - 5, y - 14, 10, 5);
    ctx.fillRect(x - 6, y - 11, 2, 3);
    ctx.fillRect(x + 4, y - 11, 1, 2);
    /* face */
    if (player.facing === 'up') {
      ctx.fillStyle = '#241b2b';
      ctx.fillRect(x - 5, y - 9, 10, 4);
    } else {
      const eyeX = player.facing === 'left' ? x - 3 : player.facing === 'right' ? x + 2 : x - 3;
      ctx.fillStyle = '#241b2b';
      ctx.fillRect(eyeX, y - 9, 1, 2);
      if (player.facing === 'down') ctx.fillRect(x + 2, y - 9, 1, 2);
      ctx.fillStyle = 'rgba(180,80,80,0.55)';
      ctx.fillRect(x - 2, y - 6, 3, 1);
    }
  }

  drawBattle(ctx, p) {
    ctx.fillStyle = 'rgba(4,3,8,0.58)';
    ctx.fillRect(0, 0, 480, 270);

    /* small NPC above the box */
    const bob = Math.sin(this.time * 2) * 1.5;
    this.drawNpc(ctx, p, 240, 128 + bob);

    /* battle box */
    ctx.fillStyle = 'rgba(5,4,10,0.95)';
    ctx.fillRect(BATTLE_BOX.x, BATTLE_BOX.y, BATTLE_BOX.w, BATTLE_BOX.h);
    ctx.strokeStyle = '#f4f1e8';
    ctx.lineWidth = 2;
    ctx.strokeRect(BATTLE_BOX.x + 1, BATTLE_BOX.y + 1, BATTLE_BOX.w - 2, BATTLE_BOX.h - 2);
    ctx.strokeStyle = 'rgba(169,139,255,0.18)';
    ctx.lineWidth = 1;
    ctx.strokeRect(BATTLE_BOX.x + 4.5, BATTLE_BOX.y + 4.5, BATTLE_BOX.w - 9, BATTLE_BOX.h - 9);

    /* projectiles */
    for (const star of this.projectiles) {
      const x = Math.round(star.x);
      const y = Math.round(star.y);
      ctx.fillStyle = star.color;
      ctx.fillRect(x - 2, y, 5, 1);
      ctx.fillRect(x, y - 2, 1, 5);
      ctx.fillRect(x - 1, y - 1, 3, 3);
      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      ctx.fillRect(x, y, 1, 1);
    }

    /* soul */
    const sx = Math.round(this.soulX ?? 236);
    const sy = Math.round(this.soulY ?? 200);
    if (this.invuln <= 0 || Math.floor(this.time * 14) % 2 === 0) {
      ctx.fillStyle = this.soulColor;
      ctx.fillRect(sx - 4, sy - 3, 2, 2);
      ctx.fillRect(sx + 2, sy - 3, 2, 2);
      ctx.fillRect(sx - 5, sy - 1, 10, 3);
      ctx.fillRect(sx - 4, sy + 2, 8, 2);
      ctx.fillRect(sx - 2, sy + 4, 4, 1);
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.fillRect(sx - 3, sy - 2, 1, 1);
    }
  }

  drawFlower(ctx, p, x, y, scale) {
    const sway = Math.sin(this.time * 1.2 + x) * 1.2;
    const cx = Math.round(x + sway);
    const h = Math.round(18 * scale);
    const glow = ctx.createRadialGradient(cx, y - h, 0, cx, y - h, 24 * scale);
    glow.addColorStop(0, 'rgba(255,215,94,0.22)');
    glow.addColorStop(1, 'rgba(255,215,94,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(cx - 24 * scale, y - h - 24 * scale, 48 * scale, 48 * scale);
    ctx.fillStyle = '#4c7a3b';
    ctx.fillRect(cx, y - h, 1, h);
    ctx.fillRect(cx - Math.round(4 * scale), y - Math.round(h * 0.55), Math.round(4 * scale), 1);
    ctx.fillStyle = p.flower;
    ctx.fillRect(cx - Math.round(4 * scale), y - h - Math.round(2 * scale), Math.round(8 * scale), Math.round(4 * scale));
    ctx.fillRect(cx - Math.round(2 * scale), y - h - Math.round(4 * scale), Math.round(4 * scale), Math.round(8 * scale));
    ctx.fillStyle = p.flowerGlow;
    ctx.fillRect(cx - Math.round(2 * scale), y - h - Math.round(2 * scale), Math.round(3 * scale), Math.round(3 * scale));
  }

  clearLine() {
    if (this.dom.dialogueText) this.dom.dialogueText.textContent = '';
  }
}

import { getLang, t } from './i18n.js';
import { getSettings, setSetting } from './settings.js';
import { audio } from './audio.js';
import { browseMods, searchMods, fetchModDetail, GAME_URL, imageUrl } from './gamebanana.js';
import {
  initStore, getAllMods, getMod, putMod, deleteMod, ensureBuiltinPack,
  inspectFile, buildLocalRecord, kindLabel, exportMod, formatBytes,
  storageInfo, downloadWithProgress, isMemoryMode
} from './store.js';
import { BUILTIN_PACKS } from './packs.js';
import {
  icon, escapeHtml, toast, openModal, closeModal, confirmDialog, busyButton, timeAgo
} from './ui.js';

const browse = {
  tab: 'browse',
  sort: 'default',
  query: '',
  page: 1,
  records: [],
  total: 0,
  hasMore: true,
  loading: false,
  error: null,
  seq: 0,
  controller: null
};

const state = {
  installed: [],
  installedById: new Map(),
  installedByMod: new Set(),
  opened: false,
  loadingInstalled: false,
  detailOpen: false,
  detailAbort: null,
  detailId: null,
  installAbort: null,
  pending: null
};

let hooks = {};
let el = {};
let searchTimer = null;

export async function initMods(options = {}) {
  hooks = {
    onLibraryChange: () => {},
    onActivePackChange: () => {},
    ...options
  };
  cacheDom();
  bindEvents();
  await initStore();
  await refreshInstalled();
  updateOnlineStatus();
  if (isMemoryMode()) {
    toast('IndexedDB недоступен: моды будут храниться только до перезагрузки.', 'error', 6000);
  }
  return { installed: state.installed };
}

function cacheDom() {
  el = {
    view: document.getElementById('modsView'),
    tabs: [...document.querySelectorAll('.mods-tab')],
    browsePane: document.getElementById('browsePane'),
    installedPane: document.getElementById('installedPane'),
    search: document.getElementById('modSearch'),
    sortChips: document.getElementById('sortChips'),
    refresh: document.getElementById('refreshBtn'),
    grid: document.getElementById('modsGrid'),
    meta: document.getElementById('browseMeta'),
    state: document.getElementById('browseState'),
    stateTitle: document.getElementById('browseStateTitle'),
    stateText: document.getElementById('browseStateText'),
    retry: document.getElementById('browseRetry'),
    loadMore: document.getElementById('loadMoreBtn'),
    browseCount: document.getElementById('browseCount'),
    installedCount: document.getElementById('installedCount'),
    libraryCount: document.getElementById('libraryCount'),
    installedSummary: document.getElementById('installedSummary'),
    installedList: document.getElementById('installedList'),
    installedEmpty: document.getElementById('installedEmpty'),
    starterGrid: document.getElementById('starterGrid'),
    dropzone: document.getElementById('dropzone'),
    fileInput: document.getElementById('fileInput'),
    importBtn: document.getElementById('importBtn'),
    importBtn2: document.getElementById('importBtn2'),
    clearInactive: document.getElementById('clearInactive'),
    gbStatus: document.getElementById('gbStatus'),
    footStatus: document.getElementById('modsFootStatus')
  };
}

function bindEvents() {
  el.tabs.forEach((tab) => tab.addEventListener('click', () => {
    audio.play('move');
    setTab(tab.dataset.tab);
  }));

  document.querySelectorAll('[data-tab-jump]').forEach((button) => {
    button.addEventListener('click', () => {
      audio.play('select');
      setTab(button.dataset.tabJump);
    });
  });

  el.search?.addEventListener('input', () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      browse.query = el.search.value.trim();
      loadBrowse(true);
    }, 460);
  });
  el.search?.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      clearTimeout(searchTimer);
      browse.query = el.search.value.trim();
      loadBrowse(true);
    } else if (event.key === 'Escape') {
      el.search.value = '';
      browse.query = '';
      loadBrowse(true);
    }
  });

  el.sortChips?.addEventListener('click', (event) => {
    const button = event.target.closest('[data-sort]');
    if (!button) return;
    audio.play('move');
    browse.sort = button.dataset.sort;
    el.sortChips.querySelectorAll('[data-sort]').forEach((chip) => chip.classList.toggle('is-active', chip === button));
    loadBrowse(true);
  });

  el.refresh?.addEventListener('click', () => {
    audio.play('download');
    loadBrowse(true);
  });
  el.retry?.addEventListener('click', () => loadBrowse(true));
  el.loadMore?.addEventListener('click', () => loadBrowse(false));

  el.grid?.addEventListener('click', (event) => {
    const card = event.target.closest('[data-mod-id]');
    if (!card) return;
    const record = browse.records.find((item) => String(item.id) === card.dataset.modId);
    if (record) openDetail(record);
  });

  const openFilePicker = () => { audio.play('select'); el.fileInput?.click(); };
  el.importBtn?.addEventListener('click', openFilePicker);
  el.importBtn2?.addEventListener('click', openFilePicker);
  el.dropzone?.addEventListener('click', openFilePicker);
  el.dropzone?.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); openFilePicker(); }
  });
  el.fileInput?.addEventListener('change', () => {
    const file = el.fileInput.files?.[0];
    el.fileInput.value = '';
    if (file) handleImport(file);
  });

  ['dragenter', 'dragover'].forEach((type) => {
    el.dropzone?.addEventListener(type, (event) => {
      event.preventDefault();
      el.dropzone.classList.add('is-over');
    });
  });
  ['dragleave', 'drop'].forEach((type) => {
    el.dropzone?.addEventListener(type, (event) => {
      event.preventDefault();
      el.dropzone.classList.remove('is-over');
    });
  });
  el.dropzone?.addEventListener('drop', (event) => {
    const file = event.dataTransfer?.files?.[0];
    if (file) handleImport(file);
  });

  el.starterGrid?.addEventListener('click', (event) => {
    const card = event.target.closest('[data-starter-id]');
    if (!card) return;
    const pack = BUILTIN_PACKS.find((item) => item.id === card.dataset.starterId);
    if (pack) activateStarter(pack);
  });

  el.installedList?.addEventListener('click', (event) => {
    const button = event.target.closest('[data-mod-action]');
    if (!button) return;
    const record = state.installedById.get(button.dataset.modId);
    if (!record) return;
    const action = button.dataset.modAction;
    if (action === 'activate') activateRecord(record);
    else if (action === 'default') activateDefault();
    else if (action === 'export') doExport(record);
    else if (action === 'delete') askDelete(record);
    else if (action === 'howto') showHowTo(record);
  });

  el.clearInactive?.addEventListener('click', clearInactive);

  window.addEventListener('online', () => {
    updateOnlineStatus();
    toast(t('mods.meta.ready'), 'ok');
  });
  window.addEventListener('offline', () => {
    updateOnlineStatus();
    toast(t('toast.offline'), 'error');
  });
}

export async function openMods() {
  if (!state.opened) {
    state.opened = true;
    loadBrowse(false);
  }
  await refreshInstalled();
  renderBrowse();
}

export function focusSearch() {
  el.search?.focus({ preventScroll: true });
}

function setTab(tab) {
  browse.tab = tab === 'installed' ? 'installed' : 'browse';
  el.tabs.forEach((button) => {
    const active = button.dataset.tab === browse.tab;
    button.classList.toggle('is-active', active);
    button.setAttribute('aria-selected', String(active));
  });
  el.browsePane?.classList.toggle('is-hidden', browse.tab !== 'browse');
  el.installedPane?.classList.toggle('is-hidden', browse.tab !== 'installed');
  if (browse.tab === 'installed') refreshInstalled();
  else if (browse.records.length === 0 && !browse.loading && !browse.error) loadBrowse(false);
}

/* ------------------------------------------------------------------ */
/* browse                                                             */
/* ------------------------------------------------------------------ */

async function loadBrowse(reset) {
  if (reset) {
    browse.page = 1;
    browse.records = [];
    browse.hasMore = true;
    browse.total = 0;
  }
  if (!browse.hasMore && !reset) return;
  browse.controller?.abort();
  const controller = new AbortController();
  browse.controller = controller;
  const seq = ++browse.seq;
  browse.loading = true;
  browse.error = null;
  renderBrowse();
  try {
    const params = { page: browse.page, signal: controller.signal };
    const result = browse.query
      ? await searchMods({ ...params, query: browse.query })
      : await browseMods({ ...params, sort: browse.sort });
    if (seq !== browse.seq) return;
    const seen = new Set(browse.records.map((record) => record.id));
    for (const record of result.records) if (!seen.has(record.id)) browse.records.push(record);
    browse.total = result.total;
    browse.hasMore = Boolean(result.more) && browse.page < 80;
    browse.page += 1;
  } catch (error) {
    if (seq !== browse.seq || controller.signal.aborted) return;
    browse.error = error;
    browse.hasMore = false;
    if (browse.records.length) toast(t('mods.toast.network'), 'error');
  } finally {
    if (seq === browse.seq) {
      browse.loading = false;
      renderBrowse();
    }
  }
}

function renderBrowse() {
  if (!el.grid) return;
  const empty = browse.records.length === 0;
  if (browse.loading && empty) {
    el.grid.innerHTML = Array.from({ length: 8 }, () => `
      <div class="mod-card is-skeleton" aria-hidden="true">
        <div class="sk-cover"></div>
        <div class="sk-line"></div>
        <div class="sk-line short"></div>
        <div class="sk-line tiny"></div>
      </div>`).join('');
  } else {
    el.grid.innerHTML = browse.records.map(cardHtml).join('');
    bindCovers(el.grid);
  }

  const showState = empty && !browse.loading;
  el.state?.classList.toggle('is-hidden', !showState);
  if (showState) {
    if (browse.error) {
      el.stateTitle.textContent = t('mods.error.title');
      el.stateText.textContent = t('mods.error.text');
      el.retry?.classList.remove('is-hidden');
    } else if (browse.query) {
      el.stateTitle.textContent = t('mods.search.empty.title');
      el.stateText.textContent = t('mods.search.empty.text');
      el.retry?.classList.add('is-hidden');
    } else {
      el.stateTitle.textContent = t('mods.detail.error');
      el.stateText.textContent = t('mods.error.text');
      el.retry?.classList.remove('is-hidden');
    }
  }

  el.loadMore?.classList.toggle('is-hidden', !browse.hasMore || browse.loading || empty);

  if (el.browseCount) el.browseCount.textContent = String(browse.records.length || browse.total || '');
  if (el.meta) {
    if (browse.loading && empty) el.meta.textContent = t('mods.loading');
    else if (browse.error) el.meta.textContent = t('mods.meta.offline');
    else if (browse.query) el.meta.textContent = t('mods.meta.search', { n: browse.records.length });
    else el.meta.textContent = t('mods.meta.browse', { n: browse.total || browse.records.length, p: Math.max(1, browse.page - 1) });
  }
  syncCardInstalled();
}

function bindCovers(root) {
  root.querySelectorAll('img[data-cover]').forEach((img) => {
    if (img.complete && img.naturalWidth) img.classList.add('is-loaded');
    img.addEventListener('load', () => img.classList.add('is-loaded'), { once: true });
    img.addEventListener('error', () => { img.remove(); }, { once: true });
  });
}

function cardHtml(record) {
  const installed = state.installedByMod.has(record.id);
  const cover = record.cover
    ? `<img data-cover src="${escapeHtml(record.cover)}" alt="" loading="lazy" decoding="async">`
    : '';
  return `
    <button class="mod-card ${installed ? 'is-installed' : ''}" type="button" data-mod-id="${record.id}" aria-label="${escapeHtml(record.name)}">
      <div class="mod-cover">
        <div class="mod-cover-placeholder">${icon('heart')}</div>
        ${cover}
        <div class="mod-badges">
          <span class="mod-cat">${escapeHtml(record.category || 'Mod')}</span>
          <span class="mod-likes">${icon('heart')}${record.likes || 0}</span>
        </div>
      </div>
      <div class="mod-card-body">
        <div class="mod-card-title">${escapeHtml(record.name)}</div>
        <div class="mod-card-author">${t('mods.card.by')} ${escapeHtml(record.author)}</div>
        <div class="mod-card-foot">
          <span class="version">${escapeHtml(record.version || 'v1.0')}</span>
          <span>${escapeHtml(timeAgo(record.dateUpdated || record.dateAdded, getLang()))}</span>
          ${installed ? `<span class="installed-flag">${icon('check')}${t('mods.card.installed')}</span>` : ''}
        </div>
      </div>
    </button>`;
}

function syncCardInstalled() {
  if (!el.grid) return;
  el.grid.querySelectorAll('[data-mod-id]').forEach((card) => {
    const installed = state.installedByMod.has(Number(card.dataset.modId));
    card.classList.toggle('is-installed', installed);
  });
}

function updateOnlineStatus() {
  const online = navigator.onLine !== false;
  if (el.gbStatus) {
    el.gbStatus.classList.toggle('is-error', !online);
    const label = el.gbStatus.querySelector('span:last-child');
    if (label) label.textContent = online ? t('mods.online') : 'OFFLINE';
  }
  if (el.footStatus) el.footStatus.textContent = online ? 'API READY' : 'OFFLINE';
}

/* ------------------------------------------------------------------ */
/* detail modal                                                       */
/* ------------------------------------------------------------------ */

function openDetail(record) {
  audio.play('select');
  state.detailId = record.id;
  state.detailOpen = true;
  state.detailAbort?.abort();
  const controller = new AbortController();
  state.detailAbort = controller;

  const initial = detailShell(record);
  const card = openModal(initial, {
    className: 'mod-detail-modal',
    onClose: () => {
      state.detailOpen = false;
      state.detailId = null;
      controller.abort();
      state.installAbort?.abort();
      state.installAbort = null;
    }
  });
  if (!card) return;
  bindCovers(card);
  bindScreens(card);
  const retry = card.querySelector('[data-detail-retry]');
  retry?.addEventListener('click', () => openDetail(record));

  fetchModDetail(record.id, { signal: controller.signal })
    .then((detail) => {
      if (!state.detailOpen || state.detailId !== record.id) return;
      renderDetail(detail);
    })
    .catch((error) => {
      if (controller.signal.aborted || !state.detailOpen) return;
      if (error?.code === 'aborted') return;
      renderDetailError(record);
    });
}

function detailShell(record) {
  return `
    <div class="mod-detail" id="modDetail">
      <div class="mod-detail-hero">
        ${record.cover ? `<img class="detail-cover" data-cover src="${escapeHtml(record.cover)}" alt="">` : ''}
        <div class="detail-stats">
          <span class="detail-stat"><b>${record.likes || 0}</b> LIKES</span>
          <span class="detail-stat"><b>${record.views || 0}</b> VIEWS</span>
          ${record.version ? `<span class="detail-stat">VER <b>${escapeHtml(record.version)}</b></span>` : ''}
        </div>
        <div class="mod-detail-head">
          <span class="detail-cat">${escapeHtml(record.category || 'MOD')}</span>
          <h2>${escapeHtml(record.name)}</h2>
          <div class="detail-author">${t('mods.card.by')} <a href="${escapeHtml(record.authorUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(record.author)}</a></div>
        </div>
      </div>
      <div class="mod-detail-body">
        <div>
          <div class="subpage-kicker">${t('mods.detail.about')}</div>
          <div class="detail-description" id="detailDescription">${t('common.loading')}</div>
          <div class="detail-screens" id="detailScreens"></div>
        </div>
        <div class="detail-side">
          <div class="install-panel" id="installPanel">
            <div class="install-panel-head"><span>${t('mods.detail.files')}</span><span class="status-dot"></span></div>
            <div class="file-list" id="detailFiles">
              <div class="file-row"><div class="file-copy"><span class="file-name">${t('common.loading')}</span></div></div>
            </div>
            <div class="install-actions">
              <div class="progress-meta is-hidden" id="detailProgressMeta"><span id="detailProgressLabel">0%</span><span id="detailProgressBytes"></span></div>
              <div class="progress is-hidden" id="detailProgress"><span id="detailProgressBar"></span></div>
              <p class="detail-note">${t('mods.detail.installNote')}</p>
              <a class="detail-link" href="${escapeHtml(record.profileUrl)}" target="_blank" rel="noopener noreferrer">${icon('external')}${t('mods.detail.view')}</a>
            </div>
          </div>
        </div>
      </div>
    </div>`;
}

function renderDetail(detail) {
  const card = document.getElementById('modDetail');
  if (!card) return;
  const description = card.querySelector('#detailDescription');
  if (description) description.textContent = detail.description || t('mods.detail.noFiles');
  const screens = card.querySelector('#detailScreens');
  if (screens) {
    screens.innerHTML = detail.images.slice(0, 6).map((img, index) => `
      <button type="button" class="${index === 0 ? 'is-active' : ''}" data-screen="${escapeHtml(img.large)}" aria-label="Screenshot ${index + 1}">
        <img src="${escapeHtml(img.small)}" alt="" loading="lazy" decoding="async">
      </button>`).join('');
    bindScreens(card);
  }
  const head = card.querySelector('.mod-detail-head');
  if (head) {
    head.querySelector('.detail-cat').textContent = detail.category || 'MOD';
    head.querySelector('h2').textContent = detail.name;
    head.querySelector('.detail-author').innerHTML = `${t('mods.card.by')} <a href="${escapeHtml(detail.authorUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(detail.author)}</a>`;
  }
  const stats = card.querySelector('.detail-stats');
  if (stats) {
    stats.innerHTML = `
      <span class="detail-stat"><b>${detail.likes || 0}</b> LIKES</span>
      <span class="detail-stat"><b>${detail.views || 0}</b> VIEWS</span>
      <span class="detail-stat"><b>${detail.downloads || 0}</b> DOWNLOADS</span>
      ${detail.version ? `<span class="detail-stat">VER <b>${escapeHtml(detail.version)}</b></span>` : ''}`;
  }
  const files = card.querySelector('#detailFiles');
  if (files) {
    if (!detail.files.length) {
      files.innerHTML = `<div class="file-row"><div class="file-copy"><span class="file-name">${t('mods.detail.noFiles')}</span></div></div>`;
    } else {
      files.innerHTML = detail.files.map((file) => {
        const already = state.installedById.has(`gb-${file.id}`);
        const ext = (file.name.split('.').pop() || 'FILE').slice(0, 4).toUpperCase();
        return `
          <div class="file-row">
            <span class="file-icon">${escapeHtml(ext)}</span>
            <div class="file-copy">
              <span class="file-name" title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</span>
              <span class="file-meta">${formatBytes(file.size)} · ${escapeHtml(timeAgo(file.date, getLang()))} · ${file.downloads || 0} DL</span>
            </div>
            <button class="file-install" type="button" data-install-file="${file.id}" aria-label="${already ? t('common.reinstall') : t('common.install')}" title="${already ? t('common.reinstall') : t('common.install')}">
              ${icon(already ? 'check' : 'download')}
            </button>
          </div>`;
      }).join('');
      files.querySelectorAll('[data-install-file]').forEach((button) => {
        button.addEventListener('click', () => {
          const file = detail.files.find((item) => String(item.id) === button.dataset.installFile);
          if (file) installGameBananaFile(detail, file, button);
        });
      });
    }
  }
  const link = card.querySelector('.detail-link');
  if (link) link.href = detail.profileUrl;
  window.__utlDetail = detail;
}

function renderDetailError(record) {
  const card = document.getElementById('modDetail');
  if (!card) return;
  const description = card.querySelector('#detailDescription');
  if (description) description.textContent = t('mods.detail.error');
  const files = card.querySelector('#detailFiles');
  if (files) {
    files.innerHTML = `
      <div class="file-row">
        <div class="file-copy"><span class="file-name">${t('mods.detail.error')}</span></div>
        <button class="file-install" type="button" data-detail-retry aria-label="${t('common.retry')}">${icon('refresh')}</button>
      </div>`;
    files.querySelector('[data-detail-retry]')?.addEventListener('click', () => openDetail(record));
  }
}

function bindScreens(root) {
  const screens = root.querySelector('.detail-screens');
  if (!screens) return;
  screens.querySelectorAll('[data-screen]').forEach((button) => {
    button.addEventListener('click', () => {
      screens.querySelectorAll('button').forEach((item) => item.classList.toggle('is-active', item === button));
      const cover = root.querySelector('.detail-cover');
      if (cover) cover.src = button.dataset.screen;
    });
  });
}

async function installGameBananaFile(detail, file, button) {
  if (state.installAbort) return;
  audio.unlock();
  audio.play('download');
  const controller = new AbortController();
  state.installAbort = controller;
  const restore = busyButton(button, '…');
  const progress = document.getElementById('detailProgress');
  const progressBar = document.getElementById('detailProgressBar');
  const progressMeta = document.getElementById('detailProgressMeta');
  const progressLabel = document.getElementById('detailProgressLabel');
  const progressBytes = document.getElementById('detailProgressBytes');
  progress?.classList.remove('is-hidden');
  progressMeta?.classList.remove('is-hidden');
  if (progressBar) progressBar.style.width = '0%';

  let timeout = setTimeout(() => controller.abort(), 180_000);
  try {
    const blob = await downloadWithProgress(file.url, (received, total) => {
      const pct = total ? Math.min(100, (received / total) * 100) : 0;
      if (progressBar) progressBar.style.width = `${pct}%`;
      if (progressLabel) progressLabel.textContent = total ? `${Math.round(pct)}%` : t('common.loading');
      if (progressBytes) progressBytes.textContent = `${formatBytes(received)}${total ? ` / ${formatBytes(total)}` : ''}`;
    }, controller.signal);
    clearTimeout(timeout);
    if (controller.signal.aborted) return;
    const localFile = new File([blob], file.name, { type: blob.type || 'application/octet-stream' });
    const inspection = await inspectFile(localFile);
    const record = {
      id: `gb-${file.id}`,
      source: 'gamebanana',
      gamebanana: { modId: detail.id, fileId: file.id, profileUrl: detail.profileUrl },
      name: detail.name,
      author: detail.author,
      version: detail.version,
      category: detail.category,
      description: detail.shortDescription || detail.description.slice(0, 400),
      cover: detail.cover,
      profileUrl: detail.profileUrl,
      fileName: file.name,
      size: blob.size,
      mime: blob.type || 'application/octet-stream',
      kind: inspection.kind,
      info: inspection.info,
      pack: inspection.kind === 'pack' ? inspection.info?.packData : null,
      md5: file.md5,
      installedAt: Date.now(),
      active: false
    };
    await putMod(record, blob);
    await refreshInstalled();
    renderBrowse();
    if (progressBar) progressBar.style.width = '100%';
    if (progressLabel) progressLabel.textContent = '100%';
    audio.play('success');
    toast(t('mods.toast.installed', { name: detail.name }), 'ok');
    if (record.kind === 'pack') {
      await activateRecord(record, { silent: true });
      toast(t('mods.import.packActive', { name: record.name }), 'ok');
    } else {
      const info = document.getElementById('installPanel');
      if (info) {
        const note = document.createElement('p');
        note.className = 'detail-note';
        note.innerHTML = `<b>${escapeHtml(kindLabel(record))}</b> · ${t('mods.detail.installNote')}`;
        info.querySelector('.install-actions')?.appendChild(note);
      }
    }
  } catch (error) {
    if (!controller.signal.aborted) {
      toast(t('mods.toast.downloadError'), 'error');
    }
  } finally {
    clearTimeout(timeout);
    state.installAbort = null;
    restore();
    setTimeout(() => {
      progress?.classList.add('is-hidden');
      progressMeta?.classList.add('is-hidden');
    }, 700);
  }
}

/* ------------------------------------------------------------------ */
/* installed library                                                  */
/* ------------------------------------------------------------------ */

export async function refreshInstalled() {
  if (state.loadingInstalled) return state.installed;
  state.loadingInstalled = true;
  try {
    const mods = await getAllMods();
    state.installed = mods;
    state.installedById = new Map(mods.map((mod) => [mod.id, mod]));
    state.installedByMod = new Set(mods.filter((mod) => mod.gamebanana?.modId).map((mod) => Number(mod.gamebanana.modId)));
    if (getSettings().activePack && !state.installedById.has(getSettings().activePack)) {
      setSetting('activePack', null);
    }
    renderStarter();
    renderInstalled();
    updateCounts();
    await updateStorage();
    hooks.onLibraryChange?.(state.installed, getSettings().activePack);
    window.dispatchEvent(new CustomEvent('utl:mods', { detail: { mods: state.installed } }));
  } catch (error) {
    console.error(error);
    toast('Не удалось прочитать библиотеку модов.', 'error');
  } finally {
    state.loadingInstalled = false;
  }
  return state.installed;
}

function renderStarter() {
  if (!el.starterGrid) return;
  el.starterGrid.innerHTML = BUILTIN_PACKS.map((pack) => {
    const installed = state.installedById.has(pack.id);
    const active = getSettings().activePack === pack.id;
    const stateText = active ? t('mods.starter.active') : installed ? t('mods.starter.activate') : t('mods.starter.install');
    const description = pack.description?.[getLang()] || pack.description?.en || '';
    return `
      <button class="starter-card" type="button" data-starter-id="${pack.id}">
        <span class="starter-swatch" style="--pack-bg:${pack.palette.bg};--pack-soul:${pack.palette.flower}"></span>
        <span class="starter-copy">
          <strong>${escapeHtml(pack.name)}</strong>
          <small>${escapeHtml(description)}</small>
        </span>
        <span class="starter-state ${active || installed ? '' : 'install'}">${escapeHtml(stateText)}</span>
      </button>`;
  }).join('');
}

function renderInstalled() {
  if (!el.installedList) return;
  const mods = [...state.installed].sort((a, b) => b.installedAt - a.installedAt);
  const active = getSettings().activePack;
  if (mods.length === 0) {
    el.installedList.innerHTML = '';
    el.installedEmpty?.classList.remove('is-hidden');
    return;
  }
  el.installedEmpty?.classList.add('is-hidden');
  el.installedList.innerHTML = mods.map((mod) => {
    const isActive = active === mod.id;
    const isPack = mod.kind === 'pack';
    const thumb = mod.cover
      ? `<img class="installed-thumb" src="${escapeHtml(mod.cover)}" alt="" loading="lazy" decoding="async">`
      : `<span class="installed-thumb installed-thumb-placeholder">${icon(isPack ? 'star' : 'puzzle')}</span>`;
    const description = mod.description ? escapeHtml(mod.description) : '';
    return `
      <div class="installed-row">
        ${thumb}
        <div class="installed-copy">
          <div class="installed-name">
            <span title="${escapeHtml(mod.name)}">${escapeHtml(mod.name)}</span>
            ${isActive ? `<span class="active-badge">${t('mods.installed.active')}</span>` : ''}
            ${isPack ? '' : `<span class="active-badge" style="border-color:rgba(169,139,255,.3);color:var(--violet)">${escapeHtml(kindLabel(mod))}</span>`}
          </div>
          <div class="installed-meta">
            <span>${escapeHtml(mod.author || 'LOCAL')}</span>
            <span>${escapeHtml(formatBytes(mod.size))}</span>
            <span>${escapeHtml(timeAgo(mod.installedAt, getLang()))}</span>
            ${mod.version ? `<span>v${escapeHtml(mod.version)}</span>` : ''}
          </div>
          ${description ? `<div class="installed-meta"><span title="${description}">${description.slice(0, 90)}${description.length > 90 ? '…' : ''}</span></div>` : ''}
        </div>
        <div class="installed-actions-row">
          ${isPack && !isActive ? `<button class="mini-btn is-primary" type="button" data-mod-action="activate" data-mod-id="${escapeHtml(mod.id)}">${icon('play')}${t('mods.installed.activate')}</button>` : ''}
          ${isPack && isActive ? `<button class="mini-btn" type="button" data-mod-action="default" data-mod-id="${escapeHtml(mod.id)}">${t('common.cancel')}</button>` : ''}
          ${!isPack ? `<button class="mini-btn" type="button" data-mod-action="howto" data-mod-id="${escapeHtml(mod.id)}">${icon('external')}${t('mods.detail.howto')}</button>` : ''}
          <button class="mini-btn" type="button" data-mod-action="export" data-mod-id="${escapeHtml(mod.id)}">${icon('download')}${t('mods.installed.export')}</button>
          <button class="mini-btn is-danger" type="button" data-mod-action="delete" data-mod-id="${escapeHtml(mod.id)}">${icon('trash')}${t('mods.installed.delete')}</button>
        </div>
      </div>`;
  }).join('');
}

function updateCounts() {
  if (el.installedCount) el.installedCount.textContent = String(state.installed.length);
  if (el.libraryCount) el.libraryCount.textContent = String(state.installed.length);
  if (el.installedSummary) {
    const size = state.installed.reduce((sum, mod) => sum + (Number(mod.size) || 0), 0);
    el.installedSummary.textContent = state.installed.length
      ? t('mods.installed.summary', { n: state.installed.length, size: formatBytes(size) })
      : t('mods.installed.desc');
  }
}

async function updateStorage() {
  const info = await storageInfo(state.installed);
  const text = document.getElementById('storageText');
  const bar = document.getElementById('storageBar');
  if (text) text.textContent = info.quota
    ? `${formatBytes(info.modBytes)} / ${formatBytes(info.quota)}`
    : formatBytes(info.modBytes);
  if (bar) {
    const pct = info.quota ? Math.min(100, (info.modBytes / info.quota) * 100) : Math.min(100, info.modBytes / (50 * 1024 * 1024) * 100);
    bar.style.width = `${pct}%`;
  }
}

async function activateStarter(pack) {
  audio.unlock();
  const existing = state.installedById.get(pack.id);
  if (existing) {
    if (getSettings().activePack === pack.id) {
      activateDefault();
      return;
    }
    await activateRecord(existing);
    return;
  }
  audio.play('download');
  try {
    await ensureBuiltinPack(pack);
    await refreshInstalled();
    await activateRecord(await getMod(pack.id));
  } catch (error) {
    toast(t('common.error'), 'error');
  }
}

async function activateRecord(record, { silent = false } = {}) {
  if (!record || record.kind !== 'pack') return;
  setSetting('activePack', record.id);
  audio.unlock();
  audio.play('success');
  if (!silent) toast(t('mods.installed.activated', { name: record.name }), 'ok');
  renderStarter();
  renderInstalled();
  hooks.onActivePackChange?.(record);
  window.dispatchEvent(new CustomEvent('utl:activepack', { detail: { record } }));
}

function activateDefault() {
  setSetting('activePack', null);
  audio.play('back');
  toast(t('mods.installed.default'), 'ok');
  renderStarter();
  renderInstalled();
  hooks.onActivePackChange?.(null);
  window.dispatchEvent(new CustomEvent('utl:activepack', { detail: { record: null } }));
}

async function doExport(record) {
  audio.unlock();
  audio.play('download');
  try {
    await exportMod(record);
    toast(t('mods.installed.exported'), 'ok');
  } catch (error) {
    toast(t('common.error'), 'error');
  }
}

async function askDelete(record) {
  audio.play('move');
  const yes = await confirmDialog({
    title: t('mods.installed.delete.title'),
    text: t('mods.installed.delete.text', { name: record.name }),
    confirmLabel: t('mods.installed.delete.confirm'),
    cancelLabel: t('common.cancel'),
    danger: true
  });
  if (!yes) return;
  await deleteMod(record.id);
  if (getSettings().activePack === record.id) {
    setSetting('activePack', null);
    hooks.onActivePackChange?.(null);
  }
  await refreshInstalled();
  renderBrowse();
  audio.play('back');
  toast(t('mods.installed.deleted'), 'ok');
}

async function clearInactive() {
  const active = getSettings().activePack;
  const targets = state.installed.filter((mod) => mod.id !== active);
  if (!targets.length) return;
  const yes = await confirmDialog({
    title: t('mods.installed.clear.title'),
    text: t('mods.installed.clear.text'),
    confirmLabel: t('common.delete'),
    cancelLabel: t('common.cancel'),
    danger: true
  });
  if (!yes) return;
  for (const mod of targets) await deleteMod(mod.id);
  await refreshInstalled();
  renderBrowse();
  toast(t('mods.installed.cleared'), 'ok');
}

/* ------------------------------------------------------------------ */
/* import                                                             */
/* ------------------------------------------------------------------ */

async function handleImport(file) {
  audio.unlock();
  if (file.size > 256 * 1024 * 1024) { toast(t('mods.import.tooBig'), 'error'); return; }
  let inspection;
  try {
    inspection = await inspectFile(file);
  } catch {
    toast(t('mods.import.invalid'), 'error');
    return;
  }
  if (inspection.kind === 'unknown' && /\.(win|zip|utmod|json)$/i.test(file.name)) {
    toast(t('mods.import.invalid'), 'error');
    return;
  }
  const record = buildLocalRecord(file, inspection);
  if (inspection.kind === 'unknown') record.kind = 'other';
  state.pending = { file, inspection, record };
  showImportModal();
}

function showImportModal() {
  const { file, inspection, record } = state.pending;
  const exists = state.installedById.has(record.id);
  const lang = getLang();
  const pack = inspection.info?.packData;
  const entryInfo = inspection.info?.entries
    ? t('mods.import.zipCount', { n: inspection.info.count || inspection.info.entries.length })
    : '';
  const rows = [
    [t('mods.import.name'), file.name],
    [t('mods.import.kind'), kindLabel(record)],
    [t('mods.import.size'), formatBytes(file.size)]
  ];
  if (pack) {
    rows.push([t('mods.import.version'), pack.version]);
    rows.push([t('mods.import.entries'), pack.name]);
  } else if (entryInfo) {
    rows.push([t('mods.import.entries'), entryInfo]);
  }
  if (inspection.info?.gameMaker) rows.push(['ENGINE', inspection.info.gameMaker]);
  if (inspection.info?.chunks) rows.push(['CHUNKS', inspection.info.chunks.slice(0, 8).join(' · ')]);
  let note = t('mods.import.noteUnknown');
  if (record.kind === 'datawin') note = t('mods.import.noteDatawin');
  else if (record.kind === 'zip-datawin') note = t('mods.import.noteZip');
  else if (record.kind === 'pack') note = t('mods.import.notePack');

  const card = openModal(`
    <div class="import-modal">
      <span class="subpage-kicker">FILE INSPECTOR // ${escapeHtml(kindLabel(record))}</span>
      <h2>${t('mods.import.title')}</h2>
      <p>${exists ? t('mods.import.exists') : t('mods.import.desc')}</p>
      <div class="import-file-info">
        <span class="file-icon">${escapeHtml((file.name.split('.').pop() || 'FILE').slice(0, 4).toUpperCase())}</span>
        <div><strong>${escapeHtml(pack?.name || record.name)}</strong><small>${escapeHtml(file.name)} · ${formatBytes(file.size)}</small></div>
      </div>
      <div class="import-facts">
        ${rows.map(([label, value]) => `<div><span>${escapeHtml(label)}</span><b>${escapeHtml(value)}</b></div>`).join('')}
      </div>
      <p class="detail-note">${escapeHtml(note)}</p>
      <div class="modal-actions">
        <button class="pixel-btn ghost" type="button" data-import-cancel>${t('common.cancel')}</button>
        <button class="pixel-btn" type="button" data-import-ok>${exists ? t('mods.import.replace') : t('mods.import.confirm')}</button>
      </div>
    </div>`, {
    className: 'import-modal-card',
    showClose: true,
    onClose: () => { state.pending = null; }
  });
  if (!card) return;
  card.querySelector('[data-import-cancel]')?.addEventListener('click', () => closeModal());
  card.querySelector('[data-import-ok]')?.addEventListener('click', (event) => confirmImport(event.currentTarget, card));
}

async function confirmImport(button, card) {
  if (!state.pending) return;
  const { file, inspection, record } = state.pending;
  const restore = busyButton(button, t('mods.import.working'));
  try {
    await putMod(record, file);
    state.pending = null;
    closeModal();
    await refreshInstalled();
    renderBrowse();
    audio.play('success');
    if (record.kind === 'pack') {
      await activateRecord(record, { silent: true });
      toast(t('mods.import.packActive', { name: record.name }), 'ok');
    } else {
      toast(t('mods.import.done', { name: record.name }), 'ok');
    }
  } catch (error) {
    restore();
    toast(t('common.error'), 'error');
  }
}

function showHowTo(record) {
  openModal(`
    <div class="import-modal">
      <span class="subpage-kicker">${escapeHtml(kindLabel(record))}</span>
      <h2>${t('mods.detail.howto')}</h2>
      <p>${t('mods.detail.howtoText')}</p>
      <div class="import-facts">
        <div><span>${t('mods.import.name')}</span><b>${escapeHtml(record.fileName || record.name)}</b></div>
        <div><span>${t('mods.import.size')}</span><b>${formatBytes(record.size)}</b></div>
        <div><span>${t('mods.import.entries')}</span><b>${escapeHtml(record.info?.gameMaker || kindLabel(record))}</b></div>
      </div>
      <p class="detail-note">${escapeHtml(t('mods.import.noteDatawin'))}</p>
      <div class="modal-actions">
        <button class="pixel-btn ghost" type="button" data-howto-export>${t('common.export')}</button>
        <button class="pixel-btn" type="button" data-modal-close>${t('common.close')}</button>
      </div>
    </div>`, { showClose: true });
  document.querySelector('[data-howto-export]')?.addEventListener('click', () => doExport(record));
}

export function getActiveRecord() {
  const id = getSettings().activePack;
  return id ? state.installedById.get(id) || null : null;
}

export function getInstalled() { return state.installed; }

