const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const OUT = process.argv[2] || 'assets';

function crc32(buf) {
  let c;
  const table = crc32.table || (crc32.table = Array.from({ length: 256 }, (_, n) => {
    c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    return c >>> 0;
  }));
  let crc = 0xffffffff;
  for (const byte of buf) crc = table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const name = Buffer.from(type, 'ascii');
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([name, data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function png(width, height, pixels) {
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (width * 4 + 1)] = 0;
    pixels.copy(raw, y * (width * 4 + 1) + 1, y * width * 4, (y + 1) * width * 4);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ]);
}

const SIZE = 512;
const px = Buffer.alloc(SIZE * SIZE * 4);

function hexColor(value) {
  const n = parseInt(value.replace('#', ''), 16);
  return n;
}

function set(x, y, color, alpha = 255) {
  if (x < 0 || y < 0 || x >= SIZE || y >= SIZE) return;
  const i = (y * SIZE + x) * 4;
  const c = typeof color === 'number' ? color : hexColor(color);
  const r = (c >> 16) & 255;
  const g = (c >> 8) & 255;
  const b = c & 255;
  if (alpha >= 255) {
    px[i] = r; px[i + 1] = g; px[i + 2] = b; px[i + 3] = 255;
    return;
  }
  const a = alpha / 255;
  px[i] = Math.round(px[i] * (1 - a) + r * a);
  px[i + 1] = Math.round(px[i + 1] * (1 - a) + g * a);
  px[i + 2] = Math.round(px[i + 2] * (1 - a) + b * a);
  px[i + 3] = Math.max(px[i + 3], Math.round(alpha));
}

function rect(x, y, w, h, color, alpha = 255) {
  for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) set(xx, yy, color, alpha);
}

function blendRect(x, y, w, h, color, alpha) {
  for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) {
    const i = (yy * SIZE + xx) * 4;
    const c = hexColor(color);
    const a = alpha / 255;
    px[i] = Math.round(px[i] * (1 - a) + ((c >> 16) & 255) * a);
    px[i + 1] = Math.round(px[i + 1] * (1 - a) + ((c >> 8) & 255) * a);
    px[i + 2] = Math.round(px[i + 2] * (1 - a) + (c & 255) * a);
    px[i + 3] = 255;
  }
}

/* background gradient */
for (let y = 0; y < SIZE; y++) {
  const t = y / SIZE;
  const top = { r: 0x1b, g: 0x13, b: 0x31 };
  const mid = { r: 0x0d, g: 0x0a, b: 0x1a };
  const bottom = { r: 0x05, g: 0x04, b: 0x0a };
  const from = t < 0.55 ? top : mid;
  const to = t < 0.55 ? mid : bottom;
  const k = t < 0.55 ? t / 0.55 : (t - 0.55) / 0.45;
  const color = (Math.round(from.r + (to.r - from.r) * k) << 16) |
    (Math.round(from.g + (to.g - from.g) * k) << 8) |
    Math.round(from.b + (to.b - from.b) * k);
  rect(0, y, SIZE, 1, color);
}

/* brick / grid texture */
for (let y = 0; y < SIZE; y += 32) blendRect(0, y, SIZE, 1, '#a98bff', 13);
for (let x = 0; x < SIZE; x += 32) blendRect(x, 0, 1, SIZE, '#a98bff', 11);

/* outer frame */
rect(0, 0, SIZE, 8, '#08060f');
rect(0, SIZE - 8, SIZE, 8, '#08060f');
rect(0, 0, 8, SIZE, '#08060f');
rect(SIZE - 8, 0, 8, SIZE, '#08060f');
rect(20, 20, SIZE - 40, 4, '#4a3478');
rect(20, SIZE - 24, SIZE - 40, 4, '#4a3478');
rect(20, 20, 4, SIZE - 40, '#4a3478');
rect(SIZE - 24, 20, 4, SIZE - 40, '#4a3478');

/* corner accents */
const gold = '#ffd75e';
const red = '#ff3b47';
rect(20, 20, 42, 5, gold);
rect(20, 20, 5, 42, gold);
rect(SIZE - 62, SIZE - 25, 42, 5, red);
rect(SIZE - 25, SIZE - 62, 5, 42, red);

/* subtle glow behind heart */
const cx = 256;
for (let r = 190; r > 40; r -= 18) {
  for (let y = -r; y <= r; y += 4) {
    for (let x = -r; x <= r; x += 4) {
      const d = Math.hypot(x, y);
      if (d < r && d > r - 18) {
        const a = Math.round(18 * (1 - d / 210));
        if (a > 0) blendRect(cx + x, 250 + y, 4, 4, '#ff3b47', a);
      }
    }
  }
}

/* pixel heart */
const HEART = [
  '011000110',
  '111101111',
  '111111111',
  '111111111',
  '011111110',
  '001111100',
  '000111000',
  '000010000'
];
const cell = 32;
const startX = cx - (9 * cell) / 2;
const startY = 250 - (8 * cell) / 2 - 14;
HEART.forEach((row, ry) => {
  [...row].forEach((bit, rx) => {
    if (bit !== '1') return;
    const x = startX + rx * cell;
    const y = startY + ry * cell;
    let color = red;
    if (ry <= 1 && rx <= 5) color = '#ff6b74';
    if (ry >= 6) color = '#a3132c';
    if (ry === 3 && rx >= 2 && rx <= 6) color = '#e02235';
    rect(x + 2, y + 2, cell - 4, cell - 4, color);
    /* dark pixel seams */
    rect(x + 2, y + 2, cell - 4, 2, 'rgba', 0);
    blendRect(x + 2, y + cell - 6, cell - 4, 4, '#7d0f22', 140);
    blendRect(x + cell - 6, y + 2, 4, cell - 4, '#7d0f22', 90);
    if (ry <= 1 && rx <= 4) blendRect(x + 8, y + 8, cell - 20, cell - 20, '#ffd0d4', 120);
  });
});

/* highlight sheen */
blendRect(198, 156, 34, 12, '#ffe1e5', 110);
blendRect(182, 168, 14, 14, '#ffe1e5', 80);

/* gold star top-right */
const star = [
  '0010000',
  '0010000',
  '0111000',
  '1111100',
  '0111000',
  '0111100',
  '1100110'
];
star.forEach((row, y) => [...row].forEach((bit, x) => {
  if (bit === '1') rect(372 + x * 12, 88 + y * 12, 12, 12, gold);
}));
blendRect(380, 92, 12, 12, '#fff6cf', 180);

/* small red sparkle bottom-left */
rect(112, 372, 10, 34, '#ff3b47');
rect(100, 384, 34, 10, '#ff3b47');
rect(112, 384, 10, 10, '#ff9da3');

/* bottom plate */
rect(132, 414, 248, 4, '#5f439e');
rect(196, 438, 120, 3, '#3a2a5e');

/* output sizes */
const sizes = [512, 192, 180, 120, 48];
for (const size of sizes) {
  if (size === SIZE) {
    fs.writeFileSync(path.join(OUT, 'icon-512.png'), png(SIZE, SIZE, px));
    continue;
  }
  const dst = Buffer.alloc(size * size * 4);
  const scale = SIZE / size;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const sx = Math.min(SIZE - 1, Math.floor(x * scale));
      const sy = Math.min(SIZE - 1, Math.floor(y * scale));
      const si = (sy * SIZE + sx) * 4;
      const di = (y * size + x) * 4;
      dst[di] = px[si];
      dst[di + 1] = px[si + 1];
      dst[di + 2] = px[si + 2];
      dst[di + 3] = px[si + 3];
    }
  }
  fs.writeFileSync(path.join(OUT, `icon-${size}.png`), png(size, size, dst));
}

console.log('icons written to', OUT);

